   // it - the point being that typing looks like it happens straight into the
   // node's own box rather than in a separate window somewhere else on screen.
   ImVec4 gCommentEditRect(0, 0, 0, 0); // x, y, w, h
   FormulaNode* gFormulaEditor = nullptr;
   bool gFormulaEditorOpen = false;
   FieldElementNode* gFieldElementEditor = nullptr;
   bool gFieldElementEditorOpen = false;
   FieldPrimitiveNode* gFieldPrimitiveEditor = nullptr;
   bool gFieldPrimitiveEditorOpen = false;
   FieldPixelNode* gFieldPixelEditor = nullptr;
   bool gFieldPixelEditorOpen = false;
   FieldSampleNode* gFieldSampleEditor = nullptr;
   bool gFieldSampleEditorOpen = false;
   FieldSynthNode* gFieldSynthEditor = nullptr;
   bool gFieldSynthEditorOpen = false;
   // Live-preview state for the Field editor windows. One editor of each
   // kind can be open at a time (singleton gField*Editor above), so a single
   // dedicated instance is enough - no per-node map needed like the node
   // body's own mini-viewports (gNodeViewports/gNodeCameras).
   NodeViewport gFieldElementEditorViewport;
   SharedViewportCamera gFieldElementEditorCamera;
   FieldGraphNode* gFieldGraphEditor = nullptr;
   bool gFieldGraphEditorOpen = false;
   // Set by a "Regenerate" button click inside DrawFieldGraphParams (nested
   // in ed::Begin()/ed::End()); drained once, outside that pass, after
   // ed::End() returns - see trap T14 and RunFieldGraphRegenerate.
   FieldGraphNode* gFieldGraphPendingRegenerate = nullptr;

   // Build step 16 ("Unpack to Canvas"). Same trap-T14 shape as
   // gFieldGraphPendingRegenerate just above: set by the "Unpack to Canvas"
   // button click inside DrawFieldGraphParams (nested in ed::Begin()/
   // ed::End()), drained once after ed::End() returns by
   // RunFieldGraphUnpackPhase1 - see that function's comment.
   FieldGraphNode* gFieldGraphPendingUnpack = nullptr;

   // Phase 2 of the unpack operation: a poll-and-validate tick driven once
   // per frame (also after ed::End(), alongside the drain above) while
   // `active` is true. Phase 1 reveals the mounted children at a provisional
   // layout and arms this; phase 2 waits for every revealed child's ed::
   // node size to read as a real measurement (not a freshly-spawned node's
   // sentinel/placeholder size - doc §3.3/trap 3) before finalizing row
   // heights and spawning the wrapping GroupNode. Capped at kMaxRetries
   // frames, after which it finalizes with the kUnpackDYMin-only fallback
   // stacking rather than waiting forever (doc's own defensive framing of
   // the "two-frame operation").
   struct FieldGraphUnpackPhase2State
   {
      bool active = false;
      FieldGraphNode* target = nullptr;
      std::vector<int> members;               // mounted indices, in layout order
      std::map<int, int> depthByIndex;        // member index -> topological depth
      std::map<int, float> columnX;           // depth -> this column's x
      int retriesLeft = 0;
      static constexpr int kMaxRetries = 10;
   };
   FieldGraphUnpackPhase2State gFieldGraphUnpackPhase2;
   bool gGlobalsOpen = false;
   bool gHelpOpen = false;
   bool gShortcutsOpen = false;
   bool gSettingsOpen = false;
   bool gShowUpdateCheckModal = false;

   // Files dropped on the window, consumed on the next frame so the spawn can
   // happen inside the editor where canvas coordinates are meaningful.
   std::vector<std::string> gDroppedFiles;
   ImVec2 gDropPos(0.0f, 0.0f);

   bool HasExtension(const std::string& path, const std::vector<std::string>& exts)
   {
      std::string cleanPath = path;
      while (cleanPath.size() > 1 && (cleanPath.back() == '/' || cleanPath.back() == '\\'))
         cleanPath.pop_back();
      size_t dot = cleanPath.find_last_of('.');
      if (dot == std::string::npos)
         return false;
      std::string ext = cleanPath.substr(dot + 1);
      std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
      for (const std::string& e : exts)
      {
         if (ext == e)
            return true;
      }
      return false;
   }

   // Shared by the OS file-drop handler and the Media search panel's
   // canvas drag-and-drop resolution, so both classify a given path
   // identically (see MediaExtensions.h).
   const std::vector<std::string>& kVideoExt = MediaExtensions::Video();
   const std::vector<std::string>& kImageExt = MediaExtensions::Image();

   // Finds the first node under a canvas-space point whose node.get()
   // dynamic_casts to T - the Samples/Media drag-drop release handler's hit
   // test, factored out so it isn't copy-pasted once per draggable node
   // type (SamplerNode, VideoSourceNode, ImageSourceNode). Deliberately a
   // plain rect test against ed::GetNodePosition/GetNodeSize rather than
   // ed::GetHoveredNode() - see the release handler's own comment for why.
   template <typename T>
   T* FindNodeUnderCanvasPoint(const ImVec2& canvasPoint)
   {
      for (GraphNode& gn : gNodes)
      {
         auto* typed = gn.node ? dynamic_cast<T*>(gn.node.get()) : nullptr;
         if (typed == nullptr)
            continue;
         const ImVec2 p = ed::GetNodePosition(gn.NodeId());
         const ImVec2 s = ed::GetNodeSize(gn.NodeId());
         if (canvasPoint.x >= p.x && canvasPoint.x <= p.x + s.x && canvasPoint.y >= p.y &&
             canvasPoint.y <= p.y + s.y)
            return typed;
      }
      return nullptr;
   }

   // Resolves a canvas-space y (ed::ScreenToCanvas'd from a drag release or
   // a file-drop's real mouse position) to a lane index against whatever
   // DrumSequencerNode last cached its grid rect during
   // DrawDrumSequencerBody - see the fields' comment on DrumSequencerNode
   // for why this is canvas space, not real screen space.
   int DrumSequencerLaneForCanvasY(DrumSequencerNode* n, float canvasY)
   {
      if (n->gridCanvasRowH <= 0.0f)
         return 0;
      const int lane = (int)((canvasY - n->gridCanvasTopY) / n->gridCanvasRowH);
      return std::clamp(lane, 0, DrumSequencerNode::kNumLanes - 1);
   }

   // Same idea, but checks each lane card's cached rect first - that's what
   // a drop landing on a card (rather than down on the step grid) is
   // actually aiming at. The grid-only version above always read as
   // "before row 0" for a card drop, since every card sits above the
   // grid's own rect, which is why every card drop used to resolve to lane
   // 0 regardless of which card the cursor was over.
   int DrumSequencerLaneForCanvasPos(DrumSequencerNode* n, float canvasX, float canvasY)
   {
      for (int lane = 0; lane < DrumSequencerNode::kNumLanes; lane++)
      {
         if (canvasX >= n->laneCardCanvasX0[lane] && canvasX <= n->laneCardCanvasX1[lane] &&
             canvasY >= n->laneCardCanvasY0[lane] && canvasY <= n->laneCardCanvasY1[lane])
            return lane;
      }
      return DrumSequencerLaneForCanvasY(n, canvasY);
   }

   void OnFilesDropped(GLFWwindow*, int count, const char** paths)
   {
      gDropPos = ImGui::GetMousePos();
      for (int i = 0; i < count; i++)
         gDroppedFiles.push_back(paths[i]);
   }

   void DropdownButton(const char* label, const std::vector<std::string>& options,
                       int current, std::function<void(int)> onSelect, float width = kParamWidth,
                       bool showCaption = true);

   // Search box + sort dropdown + type-filter dropdown for one mode of the
   // docked node-browser panel (see BrowserFilterState above). `sortNames`
   // and `typeNames` are that mode's own option lists; an empty `typeNames`
   // hides the type control entirely rather than showing a one-option
   // dropdown (Plugins does this when VST3 support isn't compiled in).
   //
   // Two rows: the search box full width on its own row (already the
   // convention every mode used before this), sort and type sharing a
   // second row at half width each - derived from the content region the
   // same way the mode tab row above derives its quarter-width, not
   // hardcoded. The ascending/descending toggle is a small arrow button
   // appended to the sort dropdown rather than a third dropdown, to keep
   // the strip to two rows.
   //
   // Returns true on any frame the query changed, or (one frame later,
   // since DropdownButton's own choice lands through the global gDropdown
   // popup rendered at the end of the frame) the sort/type/direction
   // changed. Advisory only - each mode's own cache rebuild condition
   // compares the state fields directly and is the real source of truth.
   bool DrawBrowserFilterStrip(BrowserFilterState& state,
                               const char* searchHint,
                               const std::vector<std::string>& sortNames,
                               const std::vector<std::string>& typeNames)
   {
      const BrowserFilterState before = state;

      ImGui::SetNextItemWidth(-1.0f);
      ImGui::InputTextWithHint("##browserquery", searchHint, state.query, sizeof(state.query));

      const float spacing = ImGui::GetStyle().ItemSpacing.x;
      const float avail = ImGui::GetContentRegionAvail().x;
      const float arrowW = ImGui::GetFrameHeight();
      // No trailing "sort"/"type" caption on these two (showCaption=false
      // below), so the remaining width just splits between the two
      // dropdowns and the direction-arrow button.
      const float remaining = avail - arrowW - 2.0f * spacing;
      const float typeW = typeNames.empty() ? 0.0f : std::max(40.0f, remaining * 0.5f);
      const float sortW = typeNames.empty() ? std::max(40.0f, remaining) : std::max(40.0f, remaining - typeW);

      DropdownButton("sort", sortNames, state.sortMode, [&state](int i) { state.sortMode = i; }, sortW, false);

      ImGui::SameLine();
      // Drawn as a vector triangle on the button, not a Unicode arrow
      // character - see the play/pause button's comment in
      // DrawLibrarySearchPanel: the UI font has no glyph range beyond Basic
      // Latin, so U+2191/U+2193 here rendered as a literal '?'.
      const bool dirClicked = ImGui::Button("##sortdir", ImVec2(arrowW, 0));
      {
         ImDrawList* dl = ImGui::GetWindowDrawList();
         const ImVec2 bmin = ImGui::GetItemRectMin();
         const ImVec2 bmax = ImGui::GetItemRectMax();
         const ImVec2 center((bmin.x + bmax.x) * 0.5f, (bmin.y + bmax.y) * 0.5f);
         const float iconSize = (bmax.y - bmin.y) * 0.75f;
         const ImU32 col = ImGui::IsItemHovered() ? ImGui::GetColorU32(ImGuiCol_Text) : ImGui::GetColorU32(ImGuiCol_TextDisabled);
         if (state.descending)
            Tabler::DrawChevronDown(dl, center, iconSize, col);
         else
            Tabler::DrawChevronUp(dl, center, iconSize, col);
      }
      if (dirClicked)
         state.descending = !state.descending;

      if (!typeNames.empty())
      {
         ImGui::SameLine();
         DropdownButton("type", typeNames, state.typeFilter, [&state](int i) { state.typeFilter = i; }, typeW, false);
      }

      return strcmp(before.query, state.query) != 0 || before.sortMode != state.sortMode ||
             before.typeFilter != state.typeFilter || before.descending != state.descending;
   }

   // Persisted sort/filter selections for the four browser panel modes -
   // NOT the free-typed query text, which (like the theme preset) is a
   // per-session choice, not a saved preference. Mirrors
   // CategoryColors::ThemePath()/LoadPreference(): one flat file next to the
   // app's other Application Support state, not a bundled settings format.
   // Four modes worth of three ints is a handful of numbers, so they share
   // one file rather than four.
   std::string BrowserFilterPrefsPath()
   {
      const std::string dir = AppPaths::AppSupportDir();
      return dir.empty() ? std::string() : dir + "/Infinite.browserfilters";
   }

   void LoadBrowserFilterPrefs()
   {
      const std::string path = BrowserFilterPrefsPath();
      if (path.empty())
         return;
      std::ifstream file(path);
      if (!file)
         return;
      BrowserFilterState* states[4] = { &gModulesFilter, &gSampleFilter, &gMediaFilter, &gPluginFilter };
      for (int i = 0; i < 4; i++)
      {
         int sortMode = 0, typeFilter = 0, descending = 0;
         if (!(file >> sortMode >> typeFilter >> descending))
            break;
         states[i]->sortMode = sortMode;
         states[i]->typeFilter = typeFilter;
         states[i]->descending = (descending != 0);
      }
   }

   void SaveBrowserFilterPrefs()
   {
      const std::string path = BrowserFilterPrefsPath();
      if (path.empty())
         return;
      std::ofstream file(path);
      if (!file)
         return;
      const BrowserFilterState* states[4] = { &gModulesFilter, &gSampleFilter, &gMediaFilter, &gPluginFilter };
      for (int i = 0; i < 4; i++)
         file << states[i]->sortMode << " " << states[i]->typeFilter << " " << (states[i]->descending ? 1 : 0) << "\n";
   }

   // ---- modulatable parameters --------------------------------------------
   // Every slider that can be driven by a modulator goes through ModSlider. It
   // draws an input pin beside the control, registers the parameter for this
   // frame so the modulator can write into it, and shows the live value (and
   // locks the slider) while something is patched in.
   int gCurrentNodeIndex = -1;
   int gParamCounter = 0;
   // Colour pins are counted separately from parameter pins (see
   // GraphNode::kColorBase): sharing the counter would renumber every slider
   // that follows a swatch and repoint existing patches' modulation.
   int gColorCounter = 0;
   // Discrete (bool / enum) params are numbered from their own base rather
   // than sharing gParamCounter. Giving a checkbox or a dropdown an ordinal
   // out of the float sequence would have shifted every float ordinal that
   // draws after it in the same node - repointing the modulation bindings and
   // performance-surface assignments in every patch already saved. Ordinals
   // 0..kDiscreteParamBase-1 stay exactly where they were; discrete params
   // live above that line, still inside the kParamBase..kColorBase pin block
   // (see GraphNode::kColorBase, which caps this at 800).
   const int kDiscreteParamBase = 400;
   const int kDiscreteParamSlots = 400; // 400..799
   int gDiscreteParamCounter = kDiscreteParamBase;

   // Discrete params get their ordinal from their *label*, not from draw
   // order. A draw-order counter cannot survive a node that swaps one control
   // for another when its mode changes - the note sequencer draws `rate` as a
   // dropdown in sync mode and as a knob in free mode, so every discrete param
   // below it shifted by one the instant the mode moved, and a cable patched
   // into `rate` silently re-pointed itself at `Snap to Key`. Hashing the
   // label instead pins each control to a fixed address whether or not it drew
   // this frame, so a cable into a control that is currently hidden just goes
   // inactive (the link is skipped when its pin wasn't declared - see the
   // gDrawnParamPins check in the link pass) and reattaches to the same
   // control when the mode brings it back.
   std::map<std::pair<int, std::string>, int> gDiscreteSlotByLabel;
   std::map<std::pair<int, int>, std::string> gDiscreteLabelBySlot;

   // Set while a node draws a repeated sub-panel (a Wavetable engine column,
   // and anything else that draws the same set of controls more than once in
   // one node). Discrete params take their ordinal from a hash of their label
   // alone, so two sub-panels drawing the same label collapse onto one slot -
   // one pin id emitted twice in one frame. imgui-node-editor links a node's
   // pins into a list as they are emitted, so the second emission makes the
   // list circular and the next hit-test pass spins forever: a hard hang, on
   // any patch containing that node, as soon as the cursor is over the canvas.
   // (BeginPin also guards against this now - see the duplicate-id block in
   // imgui_node_editor.cpp - but that guard costs the second control its pin,
   // so the ids still have to be distinct here.)
   //
   // ImGui::PushID() does not help: it scopes widget ids, not these ordinals.
   //
   // The first sub-panel deliberately keeps the empty scope, so its slots hash
   // exactly as they did before this existed and every binding in an already-
   // saved patch still resolves to the same control.
   std::string gDiscreteSlotScope;

   struct DiscreteSlotScope
   {
      std::string saved;
      explicit DiscreteSlotScope(int subPanelIndex)
         : saved(gDiscreteSlotScope)
      {
         if (subPanelIndex > 0)
            gDiscreteSlotScope = saved + "#" + std::to_string(subPanelIndex);
      }
      ~DiscreteSlotScope() { gDiscreteSlotScope = saved; }
   };

   int DiscreteParamSlot(int nodeIndex, const std::string& rawLabel)
   {
      const std::string label = gDiscreteSlotScope.empty() ? rawLabel
                                                           : rawLabel + gDiscreteSlotScope;
      const std::pair<int, std::string> key(nodeIndex, label);
      const auto cached = gDiscreteSlotByLabel.find(key);
      if (cached != gDiscreteSlotByLabel.end())
         return cached->second;

      // Rename-compatibility shim: map renamed discrete parameter labels to their
      // historical string so FNV-1a hash ordinal doesn't change and existing patches stay valid.
      static const std::unordered_map<std::string, std::string> kRenameAliases = {
         { "Global Scale##midiSnap", "Snap to Key##midiSnap" },
         { "Global Scale##transposeSnap", "Snap to Key##transposeSnap" },
         { "Global Scale##arpSnap", "Snap to Key##arpSnap" },
         { "Global Scale##seqSnap", "Snap to Key##seqSnap" },
         { "Global Scale##stackSnap", "Snap to Key##stackSnap" },
      };

      const std::string* hashStr = &label;
      auto aliasIt = kRenameAliases.find(label);
      if (aliasIt != kRenameAliases.end())
         hashStr = &aliasIt->second;

      // FNV-1a, so the same label lands on the same slot in every run and a
      // saved patch's bindings still resolve after a reload. Probing only
      // happens on a real collision within one node.
      uint32_t h = 2166136261u;
      for (const char c : *hashStr)
      {
         h ^= (uint8_t)c;
         h *= 16777619u;
      }
      const int start = (int)(h % (uint32_t)kDiscreteParamSlots);
      for (int probe = 0; probe < kDiscreteParamSlots; probe++)
      {
         const int cand = kDiscreteParamBase + (start + probe) % kDiscreteParamSlots;
         if (gDiscreteLabelBySlot.find({ nodeIndex, cand }) == gDiscreteLabelBySlot.end())
         {
            gDiscreteLabelBySlot[{ nodeIndex, cand }] = label;
            gDiscreteSlotByLabel[key] = cand;
            return cand;
         }
      }
      return kDiscreteParamBase; // 400 discrete params in one node: not a real case
   }

   // A node index is being reused (node deleted, patch cleared): drop its slot
   // assignments so the next occupant hashes fresh instead of inheriting them.
   void ForgetDiscreteSlots(int nodeIndex)
   {
      for (auto it = gDiscreteSlotByLabel.begin(); it != gDiscreteSlotByLabel.end();)
         it = (it->first.first == nodeIndex) ? gDiscreteSlotByLabel.erase(it) : std::next(it);
      for (auto it = gDiscreteLabelBySlot.begin(); it != gDiscreteLabelBySlot.end();)
         it = (it->first.first == nodeIndex) ? gDiscreteLabelBySlot.erase(it) : std::next(it);
   }

   void ForgetAllDiscreteSlots()
   {
      gDiscreteSlotByLabel.clear();
      gDiscreteLabelBySlot.clear();
   }
   std::set<int> gDrawnColorPins;
   // Defined further down, once the gNodes lookup exists.
   IPaletteSource* PaletteSourceByIndex(int nodeIndex);
   std::set<std::pair<int, int>> gTypedParam;                 // params showing a text field
   // Params that entered typing mode via hover+type rather than double-click;
   // these get the cursor placed at the end instead of a full selection, so
   // the seeded digit is appended to rather than replaced by the next keystroke.
   std::set<std::pair<int, int>> gTypedParamNoAutoSelect;
   // Params whose InputFloat selection/cursor state still needs to be forced
   // once the field is confirmed active (see the comment at its use site).
   std::set<std::pair<int, int>> gTypedParamPendingInit;
   // Live text for the field currently being typed into. A plain number
   // commits as a value and clears any expression; text starting with '='
   // commits as an expression (see ModSlider) - the same field doubles as
   // both, like a spreadsheet cell.
   std::map<std::pair<int, int>, std::string> gTypedParamText;

   std::string TrimCopy(const std::string& s)
   {
      size_t start = s.find_first_not_of(" \t");
      if (start == std::string::npos)
         return std::string();
      size_t end = s.find_last_not_of(" \t");
      return s.substr(start, end - start + 1);
   }
   // Param pins declared this frame. A node with its params collapsed declares
   // none, and emitting a link to an undeclared pin makes the editor treat the
   // link as dead and delete it - which silently dropped the modulation.
   std::set<int> gDrawnParamPins;
   // Set while a collapsed node runs its parameter dispatch purely to
   // re-register its params (see the params block in the node loop). Every
   // Mod* widget still assigns its ordinal and registers its ParamRef, then
   // returns immediately: no pin, no widget, no drawing. A modulator writes
   // through the pointer RegisterParam hands out, so a param that never
   // registers is a param nothing can drive - which is why closing a node's
   // eye used to silently freeze every modulator patched into it. The pins a
   // collapsed node needs are declared separately by CollapsedBindingPins,
   // so the widgets must NOT declare them again here: ed::BeginPin twice on
   // one id in a frame is undefined.
   bool gParamRegisterOnly = false;
   // Nodes to select next frame; they do not exist in the editor until they
   // have been drawn once, so selection has to wait a frame.
   std::vector<int> gPendingSelect;
   std::pair<int, int> gTypedParamJustOpened(-1, -1);
   std::vector<int> gParamPinsThisFrame;
   // Set when a right-click on a param already opened its text field this
   // frame, so the node-level right-click context menu (checked later, after
   // ed::Suspend()) knows to stay closed instead of covering the field.
   bool gParamRightClickConsumedThisFrame = false;

   void BeginNodeParams(int nodeIndex)
   {
      gCurrentNodeIndex = nodeIndex;
      gParamCounter = 0;
      gColorCounter = 0;
      gDiscreteParamCounter = kDiscreteParamBase;
   }

   // Node drawing is over: anything that draws afterwards (right/bottom-docked
   // panels, settings dialogs, the node browser) is not a node's param block.
   // Without this, gCurrentNodeIndex kept pointing at whichever node happened
   // to draw last, and every checkbox and dropdown in those panels would
   // register itself as a param of that node.
   void EndNodeParams()
   {
      gCurrentNodeIndex = -1;
      gParamCounter = 0;
      gColorCounter = 0;
      gDiscreteParamCounter = kDiscreteParamBase;
   }

   // Opens the text field for a param, seeded either from its current numeric
   // value or (if it's already driven by an expression) from that expression
   // text with its '=' prefix - used by both double-click and right-click.
   void BeginTypedEditFromCurrent(const std::pair<int, int>& editKey, int nodeIndex, int paramIndex,
                                   float* value, const char* fmt, bool hasExpr)
   {
      if (hasExpr)
      {
         const std::string* expr = Modulation::Instance().ExpressionFor(nodeIndex, paramIndex);
         gTypedParamText[editKey] = std::string("=") + (expr != nullptr ? *expr : std::string());
      }
      else
      {
         char seed[64];
         snprintf(seed, sizeof(seed), fmt, *value);
         gTypedParamText[editKey] = seed;
      }
      gTypedParam.insert(editKey);
      gTypedParamJustOpened = editKey;
      gTypedParamPendingInit.insert(editKey);
   }

   // Hovering a param (whether it's a plain slider or already showing an
   // expression) and pressing a digit/'-'/'.'/'=' jumps straight into typing
   // mode with that keystroke seeded, without needing to double-click first.
   // '=' always starts a blank formula - even over an existing one, so typing
   // '=' is a reliable way back into formula mode - and a digit always starts
   // a blank numeric entry, overriding whatever mode the param was already in.
   void HandleParamTypeHotkeys(const std::pair<int, int>& editKey, float* value)
   {
      ImGuiIO& io = ImGui::GetIO();
      for (int i = 0; i < io.InputQueueCharacters.Size; ++i)
      {
         ImWchar ch = io.InputQueueCharacters[i];
         if ((ch >= '0' && ch <= '9') || ch == '-' || ch == '.' || ch == '=')
         {
            PushUndoCheckpoint();
            if (ch == '=')
               gTypedParamText[editKey] = "=";
            else if (ch >= '0' && ch <= '9')
            {
               *value = (float)(ch - '0');
               gTypedParamText[editKey] = std::string(1, (char)ch);
            }
            else if (ch == '-')
            {
               *value = -0.0f;
               gTypedParamText[editKey] = "-";
            }
            else
            {
               *value = 0.0f;
               gTypedParamText[editKey] = ".";
            }
            gTypedParam.insert(editKey);
            gTypedParamJustOpened = editKey;
            gTypedParamNoAutoSelect.insert(editKey);
            gTypedParamPendingInit.insert(editKey);
            break;
         }
      }
   }

   // ---- audio node value readout -----------------------------------------
   // v2 showed a hovered knob's value via ImGui::SetTooltip from inside
   // ed::Begin()/ed::End() with no ed::Suspend() around it, so the node
   // editor's canvas transform was applied to the tooltip and it landed
   // offset from the cursor by an amount proportional to zoom and pan (v3
   // §1a - the "hover value floats somewhere else" report).
   //
   // The fix is not a correctly-positioned tooltip: it's not having one.
   // Every plugin this UI is benchmarked against puts the hovered/dragged
   // param's name and value in ONE fixed readout location per panel, which
   // never occludes the control being adjusted and never moves. A control
   // writes here; BeginAudioBody draws last frame's string in the node's
   // readout strip. The one-frame lag is imperceptible, and it buys a
   // strictly top-down layout with no second pass.
   std::map<int, std::string> gAudioReadout;

   void SetAudioReadout(const char* label, const char* valueText)
   {
      if (gCurrentNodeIndex < 0)
         return;
      const char* name = label;
      if (name != nullptr && name[0] == '#')
         name = "";
      char buf[96];
      snprintf(buf, sizeof(buf), "%s   %s", name != nullptr ? name : "", valueText);
      gAudioReadout[gCurrentNodeIndex] = buf;
   }

   // Widget styles for audio knobs and faders.
   enum class AudioWidgetStyle
   {
      Knob,
      VFader,
      // Same widget as VFader, routed through ConsoleFaderTaper - unity at
      // 75% of throw instead of a linear-in-dB mapping. Only meaningful for
      // a -60..+12 dB range; see the taper's own comment.
      VFaderDb,
      // Same widget as Knob, routed through ConsoleFaderTaper.
      KnobDb,
      // Logarithmic taper matching human ear frequency/pitch perception and visualizer response curves.
      KnobFreq,
      KnobLog,
      KnobSkewAttack100,
      KnobSkewDecay300,
      KnobSkewRelease400,
      KnobSkewDelay250,
      KnobSkewGlide150,
      KnobSkewGlide100,
      KnobSkewStrum30,
      KnobSkewStrum20,
      KnobSkewFreqShifter12,
      KnobSkewStereoBass120,
      KnobSkewBassMono = KnobSkewStereoBass120,
      KnobSkewSpread100 = KnobSkewFreqShifter12
   };

   // Adaptive format helper: scales display precision at small values so
   // tapered parameters do not display a static "0 ms" or dead string across the bottom sweep.
   inline void FormatAudioParam(char* outBuf, size_t outSize, const char* fmt, float val)
   {
      if (!outBuf || outSize == 0)
         return;
      if (!fmt || fmt[0] == '\0')
      {
         outBuf[0] = '\0';
         return;
      }

      if (strstr(fmt, "ms") != nullptr)
      {
         const float absV = std::fabs(val);
         if (absV < 10.0f && (strstr(fmt, "%.0f") || strstr(fmt, "%.1f")))
         {
            snprintf(outBuf, outSize, "%.2f ms", val);
            return;
         }
         if (absV < 100.0f && strstr(fmt, "%.0f"))
         {
            snprintf(outBuf, outSize, "%.1f ms", val);
            return;
         }
      }
      else if (strstr(fmt, "Hz") != nullptr)
      {
         const float absV = std::fabs(val);
         if (absV < 10.0f && (strstr(fmt, "%.0f") || strstr(fmt, "%.1f")))
         {
            snprintf(outBuf, outSize, "%.2f Hz", val);
            return;
         }
         if (absV < 100.0f && strstr(fmt, "%.0f"))
         {
            snprintf(outBuf, outSize, "%.1f Hz", val);
            return;
         }
      }
      else if (strstr(fmt, "s") != nullptr && strstr(fmt, "st") == nullptr && strstr(fmt, "step") == nullptr && strstr(fmt, "semi") == nullptr)
      {
         const float absV = std::fabs(val);
         if (absV < 0.1f && (strstr(fmt, "%.2f") || strstr(fmt, "%.1f") || strstr(fmt, "%.0f")))
         {
            snprintf(outBuf, outSize, "%.3f s", val);
            return;
         }
         if (absV < 1.0f && (strstr(fmt, "%.1f") || strstr(fmt, "%.0f")))
         {
            snprintf(outBuf, outSize, "%.2f s", val);
            return;
         }
      }

      snprintf(outBuf, outSize, fmt, val);
   }

   // Skew (power law) taper parameterized by target 12 o'clock centre value.
   // Follows JUCE's NormalisableRange::setSkewForCentre idiom:
   // k = ln((centre - minV) / (maxV - minV)) / ln(0.5)
   // PosToValue(p) = minV + (maxV - minV) * p^k
   // ValueToPos(v) = ((v - minV) / (maxV - minV))^(1/k)
   namespace SkewTaperMath
   {
      inline float PosToValue(float pos01, float minV, float maxV, float centre)
      {
         if (maxV <= minV || centre <= minV || centre >= maxV)
            return minV + (maxV - minV) * std::clamp(pos01, 0.0f, 1.0f);
         const float k = logf((centre - minV) / (maxV - minV)) / logf(0.5f);
         return minV + (maxV - minV) * powf(std::clamp(pos01, 0.0f, 1.0f), k);
      }

      inline float ValueToPos(float value, float minV, float maxV, float centre)
      {
         if (maxV <= minV || centre <= minV || centre >= maxV)
            return (maxV > minV) ? std::clamp((value - minV) / (maxV - minV), 0.0f, 1.0f) : 0.0f;
         const float k = logf((centre - minV) / (maxV - minV)) / logf(0.5f);
         const float norm = std::clamp((value - minV) / (maxV - minV), 0.0f, 1.0f);
         return std::clamp(powf(norm, 1.0f / k), 0.0f, 1.0f);
      }
   }

   // True logarithmic taper for ranges with minV > 0.
   // Maps 0..1 throw to an octave/ratio-linear scale between minV and maxV.
   namespace LogTaper
   {
      inline float PosToValue(float pos01, float minV, float maxV)
      {
         const float lo = std::max(1e-4f, minV);
         const float hi = std::max(lo + 1e-4f, maxV);
         return lo * powf(hi / lo, std::clamp(pos01, 0.0f, 1.0f));
      }

      inline float ValueToPos(float value, float minV, float maxV)
      {
         const float lo = std::max(1e-4f, minV);
         const float hi = std::max(lo + 1e-4f, maxV);
         const float clampedVal = std::clamp(value, lo, hi);
         return std::clamp((logf(clampedVal) - logf(lo)) / (logf(hi) - logf(lo)), 0.0f, 1.0f);
      }
   }

   namespace FrequencyTaper
   {
      inline float PosToValue(float pos01, float minV, float maxV) { return LogTaper::PosToValue(pos01, minV, maxV); }
      inline float ValueToPos(float value, float minV, float maxV) { return LogTaper::ValueToPos(value, minV, maxV); }
   }

   namespace SkewAttack100Taper
   {
      inline float PosToValue(float pos01, float minV, float maxV) { return SkewTaperMath::PosToValue(pos01, minV, maxV, 100.0f); }
      inline float ValueToPos(float value, float minV, float maxV) { return SkewTaperMath::ValueToPos(value, minV, maxV, 100.0f); }
   }

   namespace SkewDecay300Taper
   {
      inline float PosToValue(float pos01, float minV, float maxV) { return SkewTaperMath::PosToValue(pos01, minV, maxV, 300.0f); }
      inline float ValueToPos(float value, float minV, float maxV) { return SkewTaperMath::ValueToPos(value, minV, maxV, 300.0f); }
   }

