   void DrawNoteSwitcherBody(GraphNode& gn, NoteSwitcherNode* n)
   {
      const int active = n->ActiveSlot();
      char stat[64];
      if (n->manual)
         snprintf(stat, sizeof(stat), "manual  -  slot %d", active + 1);
      else if (n->rateMode == 0)
      {
         int div = NearestRateDivision(n->rateBeats);
         snprintf(stat, sizeof(stat), "every %s  -  slot %d", MusicTime::RateDivisionName(div), active + 1);
      }
      else
         snprintf(stat, sizeof(stat), "every %.2fs  -  slot %d", n->rateSeconds, active + 1);

      BeginAudioBody(gn.index, gn.category, kAudioNarrowWidth, stat);

      // Four LED dots: active slot lit, connected dim, unconnected darkest
      {
         const float w = gAudioBodyW;
         const ImVec2 origin = ImGui::GetCursorScreenPos();
         ImDrawList* dl = ImGui::GetWindowDrawList();
         const float dia = 14.0f;
         const float gap = (w - (float)NoteSwitcherNode::kSlots * dia) / (float)(NoteSwitcherNode::kSlots + 1);
         for (int i = 0; i < NoteSwitcherNode::kSlots; i++)
         {
            const float cx = origin.x + gap * (float)(i + 1) + dia * (float)i + dia * 0.5f;
            const bool isConnected = n->noteInputs[i].IsConnected();
            const bool isActive = (i == active);
            ImU32 col = IM_COL32(50, 53, 64, 255); // unconnected darkest
            if (isActive)
               col = IM_COL32(120, 200, 255, 255); // active lit
            else if (isConnected)
               col = IM_COL32(70, 120, 170, 255); // connected dim
            dl->AddCircleFilled(ImVec2(cx, origin.y + dia * 0.5f), dia * 0.5f, col);
         }
         ImGui::Dummy(ImVec2(w, dia + 6.0f));
      }

      {
         AudioKnobRow row(2);
         DrawRateModeControls(row, &n->rateMode, &n->rateBeats, &n->rateSeconds);
         row.End();
      }

      {
         AudioKnobRow row(2, 20.0f, 0.0f, false);
         row.Checkbox("manual##switcherManual", &n->manual);
         row.End();
      }
      if (n->manual)
      {
         ModSliderInt("slot", &n->manualSlot, 0, NoteSwitcherNode::kSlots - 1);
      }

      EndAudioBody();
   }

   void DrawNoteRouterBody(GraphNode& gn, NoteRouterNode* n)
   {
      static const std::vector<std::string> kModes = { "Round Robin", "Random", "Probability", "Chain" };
      const int mask = n->LastRoutedMask();
      char stat[64];
      snprintf(stat, sizeof(stat), "%s%s", kModes[std::clamp(n->mode, 0, 3)].c_str(),
               mask == 0 ? "" : " - active");

      BeginAudioBody(gn.index, gn.category, kAudioNarrowWidth, stat);

      // Four lit dots showing which outputs are currently carrying a held note.
      {
         const float w = gAudioBodyW;
         const ImVec2 origin = ImGui::GetCursorScreenPos();
         ImDrawList* dl = ImGui::GetWindowDrawList();
         const float dia = 14.0f;
         const float gap = (w - 4.0f * dia) / 5.0f;
         for (int o = 0; o < 4; o++)
         {
            const float cx = origin.x + gap * (float)(o + 1) + dia * (float)o + dia * 0.5f;
            const bool lit = (mask & (1 << o)) != 0;
            dl->AddCircleFilled(ImVec2(cx, origin.y + dia * 0.5f), dia * 0.5f,
                                lit ? IM_COL32(120, 200, 255, 255) : IM_COL32(50, 53, 64, 255));
         }
         ImGui::Dummy(ImVec2(w, dia + 6.0f));
      }

      {
         const bool showProb = n->mode == NoteRouterNode::kProbability;
         AudioKnobRow row(showProb ? 2 : 1);
         row.Dropdown("mode", kModes, n->mode, [n](int i) { PushUndoCheckpoint(); n->mode = i; });
         if (showProb)
            row.Knob("prob", &n->probability, 0.0f, 100.0f, "%.0f%%", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   // Drag state for the gate grid's paint gesture - file-scope like
   // gDrumGridDrag, since a drag spans many frames and many per-cell
   // InvisibleButton calls. A distinct struct from the drum grid's (rather
   // than reused) since this one has no lane dimension, just a step origin.
   struct ArpGateDragState
   {
      bool active = false;
      bool paintOn = false;
      int originStep = -1;
   };
   ArpGateDragState gArpGateDrag;

   // The 8-step gate grid: both the visualizer and the primary editable
   // control (replaces the old per-mode decorative shape, which couldn't
   // scale to 15 modes and wasn't interactive). Click/drag-paint toggles a
   // step's gate; the currently-sounding step lights up as the playhead.
   void DrawArpGateGrid(ArpeggiatorNode* n)
   {
      const int steps = ArpeggiatorNode::kGateSteps;
      const float gap = 3.0f;
      const float w = gAudioBodyW;
      const float cellW = (w - gap * (float)(steps - 1)) / (float)steps;
      const float h = std::min(cellW, 46.0f);
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      ImDrawList* dl = ImGui::GetWindowDrawList();
      const int playStep = n->CurrentGridStep();

      for (int s = 0; s < steps; s++)
      {
         const float x0 = origin.x + (float)s * (cellW + gap);
         const ImVec2 cellMin(x0, origin.y);
         const ImVec2 cellMax(x0 + cellW, origin.y + h);

         ImGui::PushID(s);
         ImGui::SetCursorScreenPos(cellMin);
         ImGui::InvisibleButton("gatecell", ImVec2(cellW, h));

         const bool wasOn = ((n->stepGates >> s) & 1) != 0;
         if (ImGui::IsItemActivated())
         {
            PushUndoCheckpoint();
            if (wasOn)
               n->stepGates &= ~(1 << s);
            else
               n->stepGates |= (1 << s);
            gArpGateDrag.active = true;
            gArpGateDrag.paintOn = !wasOn;
            gArpGateDrag.originStep = s;
         }
         else if (gArpGateDrag.active && s != gArpGateDrag.originStep && ImGui::IsMouseDown(ImGuiMouseButton_Left) &&
                  ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenBlockedByActiveItem))
         {
            if (gArpGateDrag.paintOn)
               n->stepGates |= (1 << s);
            else
               n->stepGates &= ~(1 << s);
         }

         const bool on = ((n->stepGates >> s) & 1) != 0;
         const bool isPlayhead = (playStep == s);

         const bool isLight = IsThemeLight();
         dl->AddRectFilled(cellMin, cellMax, isLight ? IM_COL32(220, 225, 235, 255) : IM_COL32(11, 12, 16, 255), 4.0f);
         if (on)
            dl->AddRectFilled(cellMin, cellMax,
                               isPlayhead ? (isLight ? IM_COL32(255, 255, 255, 255) : IM_COL32(225, 242, 255, 255))
                                          : (isLight ? IM_COL32(40, 120, 235, 240) : IM_COL32(150, 214, 255, 200)), 4.0f);
         dl->AddRect(cellMin, cellMax, isPlayhead ? (isLight ? IM_COL32(30, 100, 230, 255) : IM_COL32(255, 255, 255, 255))
                                                  : (isLight ? IM_COL32(180, 188, 204, 255) : IM_COL32(64, 68, 84, 255)), 4.0f,
                     0, isPlayhead ? 2.0f : 1.0f);

         ImGui::PopID();
      }

      if (ImGui::IsMouseReleased(ImGuiMouseButton_Left))
         gArpGateDrag.active = false;

      ImGui::SetCursorScreenPos(origin);
      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawArpeggiatorBody(GraphNode& gn, ArpeggiatorNode* n)
   {
      // Display order per the design ask; enum values (mode's serialized
      // int) must not move, so this is a separate indirection rather than
      // a reorder of the enum itself - see ArpeggiatorNode::Mode's comment.
      static const std::vector<std::string> kModeLabels = {
         "Up", "Down", "Up/Down", "Down/Up", "Random", "As Played", "Repeat x2", "Repeat x4",
         "Join", "Spread", "Join/Spread", "Stairs Up", "Stairs Down", "Diverge", "Converge",
      };
      static const int kModeValues[] = {
         ArpeggiatorNode::kUp,        ArpeggiatorNode::kDown,       ArpeggiatorNode::kUpDown,
         ArpeggiatorNode::kDownUp,    ArpeggiatorNode::kRandom,     ArpeggiatorNode::kAsPlayed,
         ArpeggiatorNode::kRepeat2,   ArpeggiatorNode::kRepeat4,    ArpeggiatorNode::kJoin,
         ArpeggiatorNode::kSpread,    ArpeggiatorNode::kJoinSpread, ArpeggiatorNode::kStairsUp,
         ArpeggiatorNode::kStairsDown, ArpeggiatorNode::kDiverge,   ArpeggiatorNode::kConverge,
      };
      int modeUiIndex = 0;
      for (int i = 0; i < (int)kModeLabels.size(); i++)
         if (kModeValues[i] == n->mode) { modeUiIndex = i; break; }

      char stat[64];
      const int cur = n->CurrentNote();
      if (cur < 0)
         snprintf(stat, sizeof(stat), "%d held", n->HeldCount());
      else
         snprintf(stat, sizeof(stat), "%s%d", NoteNameList()[cur % 12].c_str(), cur / 12 - 1);

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      DrawArpGateGrid(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(3);
         row.Dropdown("preset", ArpeggiatorNode::PresetNames(), n->mLastPresetUiIndex,
                      [n](int i) { PushUndoCheckpoint(); n->mLastPresetUiIndex = i; n->ApplyPreset(i); });
         row.Dropdown("mode", kModeLabels, modeUiIndex,
                      [n](int i) { PushUndoCheckpoint(); n->mode = kModeValues[std::clamp(i, 0, (int)kModeLabels.size() - 1)]; });
         row.KnobInt("octaves", &n->octaves, 1, 4);
         row.End();
      }
      {
         AudioKnobRow row(3);
         DrawRateModeControls(row, &n->rateMode, &n->rateBeats, &n->rateSeconds);
         row.Knob("gate", &n->gatePercent, 1.0f, 100.0f, "%.0f%%", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   void DrawNoteSequencerBody(GraphNode& gn, NoteSequencerNode* n)
   {
      const int cur = n->CurrentStep();
      const int steps = std::clamp(n->steps, 1, NoteSequencerNode::kMaxSteps);
      char stat[80];
      if (cur >= 0 && cur < steps)
      {
         int playNote = n->stepNote[cur];
         if (n->useGlobalScale)
            playNote = MusicTime::SnapToScale(playNote, Transport::Instance().Key(), Transport::Instance().Scale(), MusicTime::kSnapNearest);
         playNote = std::clamp(playNote, 0, 127);
         snprintf(stat, sizeof(stat), "step %d/%d - %s%d (%+dst)%s",
                  cur + 1, steps,
                  NoteNameList()[playNote % 12].c_str(), playNote / 12 - 1,
                  playNote - 60,
                  n->stepEnabled[cur] ? "" : " [muted]");
      }
      else
      {
         snprintf(stat, sizeof(stat), "step 0/%d", steps);
      }

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      int hoverStep = -1;
      {
         const float w = gAudioBodyW;
         const float pitchH = 170.0f;
         const float velH = 22.0f;
         const float totalGridH = pitchH + velH;
         const float gap = 2.0f;
         const float barW = (w - gap * (float)(steps - 1)) / (float)steps;
         const ImVec2 origin = ImGui::GetCursorScreenPos();
         const ImVec2 br(origin.x + w, origin.y + totalGridH);
         ImDrawList* dl = ImGui::GetWindowDrawList();
         ImFont* font = ImGui::GetFont();
         const bool isLight = IsThemeLight();

         const int kLow = 36, kHigh = 84; // C2..C6 (-24..+24 st, 49 notes)
         const int numNotes = kHigh - kLow + 1;
         const float noteH = pitchH / (float)numNotes;

         auto DrawTextCentered = [&](const ImVec2& minP, const ImVec2& maxP, ImU32 col, const char* text, float fSz) {
            const ImVec2 sz = font->CalcTextSizeA(fSz, FLT_MAX, 0.0f, text);
            const float tx = minP.x + std::max(0.0f, (maxP.x - minP.x - sz.x) * 0.5f);
            const float ty = minP.y + std::max(0.0f, (maxP.y - minP.y - sz.y) * 0.5f);
            dl->AddText(font, fSz, ImVec2(tx, ty), col, text);
         };

         // ---- 1) Container chassis ----
         dl->AddRectFilled(origin, br, isLight ? IM_COL32(236, 240, 248, 255) : IM_COL32(16, 16, 22, 255), 4.0f);

         // ---- 2) Octave guide lines across pitch area ----
         const int octaveNotes[] = { 48, 60, 72 }; // C3, C4, C5
         for (int octNote : octaveNotes)
         {
            const float lineY = origin.y + (float)(kHigh - octNote) * noteH;
            const bool isMiddleC = (octNote == 60);
            const ImU32 lineCol = isMiddleC
               ? (isLight ? IM_COL32(175, 182, 198, 220) : IM_COL32(65, 70, 88, 220))
               : (isLight ? IM_COL32(210, 215, 226, 150) : IM_COL32(32, 35, 46, 150));
            dl->AddLine(ImVec2(origin.x + 2.0f, lineY), ImVec2(br.x - 2.0f, lineY), lineCol, isMiddleC ? 1.5f : 1.0f);
         }

         // Divider line between pitch matrix and velocity lane
         dl->AddLine(ImVec2(origin.x, origin.y + pitchH), ImVec2(br.x, origin.y + pitchH),
                     isLight ? IM_COL32(200, 206, 218, 255) : IM_COL32(40, 44, 56, 255), 1.0f);

         // ---- 3) Step Columns ----
         for (int i = 0; i < steps; i++)
         {
            const float x0 = origin.x + (float)i * (barW + gap);
            const float x1 = x0 + barW;
            const bool isCurrent = (i == cur);
            const bool isGroupStart = (i % 4) == 0;
            ImGui::PushID(i);

            // Column track background
            const ImU32 trackCol = isLight
               ? (isGroupStart ? IM_COL32(214, 220, 232, 255) : IM_COL32(226, 230, 240, 255))
               : (isGroupStart ? IM_COL32(32, 35, 46, 255) : IM_COL32(22, 24, 32, 255));
            dl->AddRectFilled(ImVec2(x0, origin.y), ImVec2(x1, origin.y + pitchH), trackCol, 2.0f);

            // ---- Pitch interactive area ----
            ImGui::SetCursorScreenPos(ImVec2(x0, origin.y));
            ImGui::InvisibleButton("pitch", ImVec2(barW, pitchH));
            const bool pitchHovered = ImGui::IsItemHovered();
            const bool pitchActive = ImGui::IsItemActive();
            if (pitchHovered)
               hoverStep = i;

            // Double click or right click to toggle gate / mute
            if (ImGui::IsItemHovered() && ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left))
            {
               PushUndoCheckpoint();
               n->stepEnabled[i] = !n->stepEnabled[i];
            }
            else if (ImGui::IsItemClicked(ImGuiMouseButton_Right))
            {
               PushUndoCheckpoint();
               n->stepEnabled[i] = !n->stepEnabled[i];
            }
            else if (pitchActive && (ImGui::IsMouseDragging(ImGuiMouseButton_Left, 0.0f) || ImGui::IsItemClicked(ImGuiMouseButton_Left)))
            {
               const float my = ImGui::GetIO().MousePos.y;
               const float t = 1.0f - std::clamp((my - origin.y) / pitchH, 0.0f, 1.0f);
               n->stepNote[i] = std::clamp(kLow + (int)std::floor(t * (float)numNotes), kLow, kHigh);
            }

            // Calculate display note
            const int rawNote = n->stepNote[i];
            int dispNote = rawNote;
            if (n->useGlobalScale)
               dispNote = MusicTime::SnapToScale(rawNote, Transport::Instance().Key(), Transport::Instance().Scale(), MusicTime::kSnapNearest);
            dispNote = std::clamp(dispNote, kLow, kHigh);
            const int dispPc = ((dispNote % 12) + 12) % 12;
            const int dispOct = dispNote / 12 - 1;

            const float noteTopY = origin.y + (float)(kHigh - dispNote) * noteH;
            const float capH = std::max(15.0f, noteH + 2.5f);
            const float capTop = std::clamp(noteTopY - (capH - noteH) * 0.5f, origin.y, origin.y + pitchH - capH);
            const float capBot = capTop + capH;

            // Playhead column wash or hover highlight
            if (isCurrent)
            {
               dl->AddRectFilled(ImVec2(x0, origin.y), ImVec2(x1, origin.y + pitchH),
                                 isLight ? IM_COL32(255, 200, 80, 50) : IM_COL32(255, 190, 80, 35), 2.0f);
            }
            else if (pitchHovered)
            {
               dl->AddRectFilled(ImVec2(x0, origin.y), ImVec2(x1, origin.y + pitchH),
                                 isLight ? IM_COL32(0, 0, 0, 10) : IM_COL32(255, 255, 255, 12), 2.0f);
            }

            // Pitch bar stem (from cap to bottom of pitch area)
            if (capBot < origin.y + pitchH)
            {
               const ImU32 stemCol = n->stepEnabled[i]
                  ? (isCurrent
                        ? (isLight ? IM_COL32(235, 145, 30, 160) : IM_COL32(225, 170, 50, 150))
                        : (isLight ? IM_COL32(45, 125, 230, 150) : IM_COL32(60, 140, 235, 140)))
                  : (isLight ? IM_COL32(195, 200, 210, 90) : IM_COL32(38, 42, 54, 90));
               dl->AddRectFilled(ImVec2(x0 + 1.0f, capBot), ImVec2(x1 - 1.0f, origin.y + pitchH),
                                 stemCol, 2.0f);
            }

            // Note pill cap
            const float fontCapSz = steps <= 8 ? 10.5f : (steps <= 12 ? 9.5f : 8.5f);
            if (n->stepEnabled[i])
            {
               const ImU32 capCol = isCurrent
                  ? (isLight ? IM_COL32(245, 155, 25, 255) : IM_COL32(255, 200, 80, 255))
                  : (pitchActive
                        ? (isLight ? IM_COL32(20, 105, 220, 255) : IM_COL32(120, 195, 255, 255))
                        : (isLight ? IM_COL32(35, 120, 235, 255) : IM_COL32(80, 170, 255, 255)));
               const ImU32 capBorder = isCurrent
                  ? (isLight ? IM_COL32(255, 230, 140, 255) : IM_COL32(255, 245, 180, 255))
                  : (isLight ? IM_COL32(160, 205, 255, 200) : IM_COL32(180, 230, 255, 180));

               dl->AddRectFilled(ImVec2(x0 + 1.0f, capTop), ImVec2(x1 - 1.0f, capBot), capCol, 3.0f);
               dl->AddRect(ImVec2(x0 + 1.0f, capTop), ImVec2(x1 - 1.0f, capBot), capBorder, 3.0f);

               char noteStr[16];
               snprintf(noteStr, sizeof(noteStr), "%s%d", NoteNameList()[dispPc].c_str(), dispOct);
               const ImU32 txtCol = isCurrent
                  ? IM_COL32(20, 15, 5, 255)
                  : (isLight ? IM_COL32(255, 255, 255, 255) : IM_COL32(10, 20, 35, 255));
               DrawTextCentered(ImVec2(x0 + 1.0f, capTop), ImVec2(x1 - 1.0f, capBot), txtCol, noteStr, fontCapSz);
            }
            else
            {
               const ImU32 capCol = isLight ? IM_COL32(208, 213, 224, 200) : IM_COL32(40, 44, 56, 200);
               const ImU32 capBorder = isLight ? IM_COL32(175, 182, 196, 180) : IM_COL32(65, 70, 85, 180);
               dl->AddRectFilled(ImVec2(x0 + 1.0f, capTop), ImVec2(x1 - 1.0f, capBot), capCol, 3.0f);
               dl->AddRect(ImVec2(x0 + 1.0f, capTop), ImVec2(x1 - 1.0f, capBot), capBorder, 3.0f);

               char noteStr[16];
               snprintf(noteStr, sizeof(noteStr), "%s%d", NoteNameList()[dispPc].c_str(), dispOct);
               const ImU32 txtCol = isLight ? IM_COL32(130, 136, 152, 200) : IM_COL32(105, 110, 125, 180);
               DrawTextCentered(ImVec2(x0 + 1.0f, capTop), ImVec2(x1 - 1.0f, capBot), txtCol, noteStr, fontCapSz);
            }

            // ---- Velocity lane ----
            const float vy0 = origin.y + pitchH;
            const float vy1 = vy0 + velH;
            ImGui::SetCursorScreenPos(ImVec2(x0, vy0));
            ImGui::InvisibleButton("vel", ImVec2(barW, velH));
            const bool velHovered = ImGui::IsItemHovered();
            const bool velActive = ImGui::IsItemActive();
            if (velHovered)
               hoverStep = i;

            if (ImGui::IsItemHovered() && ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left))
            {
               PushUndoCheckpoint();
               n->stepEnabled[i] = !n->stepEnabled[i];
            }
            else if (ImGui::IsItemClicked(ImGuiMouseButton_Right))
            {
               PushUndoCheckpoint();
               n->stepEnabled[i] = !n->stepEnabled[i];
            }
            else if (velActive && (ImGui::IsMouseDragging(ImGuiMouseButton_Left, 0.0f) || ImGui::IsItemClicked(ImGuiMouseButton_Left)))
            {
               const float my = ImGui::GetIO().MousePos.y;
               const float vt = 1.0f - std::clamp((my - vy0) / velH, 0.0f, 1.0f);
               n->stepVelocity[i] = std::clamp(vt, 0.0f, 1.0f);
               n->stepEnabled[i] = true;
            }

            // Velocity track background
            const ImU32 velTrackCol = isLight ? IM_COL32(220, 225, 236, 255) : IM_COL32(18, 20, 26, 255);
            dl->AddRectFilled(ImVec2(x0 + 1.0f, vy0 + 1.0f), ImVec2(x1 - 1.0f, vy1 - 1.0f), velTrackCol, 2.0f);

            const float fontVelSz = steps <= 8 ? 9.5f : 8.5f;
            if (n->stepEnabled[i])
            {
               const float vFillTop = vy1 - n->stepVelocity[i] * (velH - 2.0f) - 1.0f;
               const ImU32 vCol = isCurrent
                  ? (isLight ? IM_COL32(235, 145, 30, 240) : IM_COL32(255, 205, 90, 255))
                  : (isLight ? IM_COL32(40, 165, 100, 230) : IM_COL32(65, 205, 135, 240));
               dl->AddRectFilled(ImVec2(x0 + 1.0f, vFillTop), ImVec2(x1 - 1.0f, vy1 - 1.0f), vCol, 2.0f);

               char vStr[16];
               snprintf(vStr, sizeof(vStr), "%.0f", n->stepVelocity[i] * 100.0f);
               const ImU32 txtVCol = isLight ? IM_COL32(10, 25, 15, 230) : IM_COL32(10, 25, 15, 230);
               DrawTextCentered(ImVec2(x0 + 1.0f, vy0), ImVec2(x1 - 1.0f, vy1), txtVCol, vStr, fontVelSz);
            }
            else
            {
               DrawTextCentered(ImVec2(x0 + 1.0f, vy0), ImVec2(x1 - 1.0f, vy1),
                                isLight ? IM_COL32(140, 145, 160, 180) : IM_COL32(85, 90, 105, 180), "OFF", fontVelSz);
            }

            // Playhead column outline
            if (isCurrent)
            {
               dl->AddRect(ImVec2(x0, origin.y), ImVec2(x1, vy1),
                           isLight ? IM_COL32(225, 130, 20, 240) : IM_COL32(255, 210, 80, 230), 2.0f, 0, 1.5f);
            }

            // ---- Step number label below each column (Pattern-style) ----
            char label[8];
            snprintf(label, sizeof(label), "%d", i + 1);
            // Cap at the ambient UI font size and only shrink below it once a
            // column gets too narrow to fit a number at that size - the old
            // `steps > 8 ? barW * 0.95f` branch scaled font size UP with
            // column width instead of down, so going from 8 to 9+ steps (still
            // ~45px-wide columns at this node width) jumped the step numbers
            // to ~3x the normal text size instead of shrinking them.
            const float labelFontSize = std::min(ImGui::GetFontSize(), std::max(8.0f, barW * 0.95f));
            const ImVec2 textSize = font->CalcTextSizeA(labelFontSize, FLT_MAX, 0.0f, label);
            const ImU32 stepNumCol = isCurrent
               ? (isLight ? IM_COL32(225, 130, 20, 255) : IM_COL32(255, 200, 80, 255))
               : (isLight
                     ? (isGroupStart ? IM_COL32(40, 48, 65, 255) : IM_COL32(110, 116, 132, 255))
                     : (isGroupStart ? IM_COL32(190, 194, 210, 255) : IM_COL32(110, 114, 130, 255)));
            dl->AddText(font, labelFontSize, ImVec2(x0 + (barW - textSize.x) * 0.5f, br.y + 3.0f),
                        stepNumCol, label);

            ImGui::PopID();
         }

         // Grid outer border
         dl->AddRect(origin, br, isLight ? IM_COL32(185, 192, 208, 255) : IM_COL32(65, 70, 85, 255), 4.0f);

         const float labelRowH = ImGui::GetFontSize() + 5.0f;
         ImGui::SetCursorScreenPos(ImVec2(origin.x, br.y + labelRowH));
         if (hoverStep >= 0)
         {
            const int rawNote = n->stepNote[hoverStep];
            int dispNote = rawNote;
            if (n->useGlobalScale)
               dispNote = MusicTime::SnapToScale(rawNote, Transport::Instance().Key(), Transport::Instance().Scale(), MusicTime::kSnapNearest);
            dispNote = std::clamp(dispNote, kLow, kHigh);
            const int dispPc = ((dispNote % 12) + 12) % 12;
            const int dispOct = dispNote / 12 - 1;
            const int stFromC4 = dispNote - 60;
            if (n->stepEnabled[hoverStep])
               ImGui::TextDisabled("step %d: %s%d (%+dst) | vel %.0f%% (dbl-click to mute)",
                                   hoverStep + 1, NoteNameList()[dispPc].c_str(), dispOct, stFromC4,
                                   n->stepVelocity[hoverStep] * 100.0f);
            else
               ImGui::TextDisabled("step %d: %s%d (%+dst) [MUTED] (dbl-click to unmute)",
                                   hoverStep + 1, NoteNameList()[dispPc].c_str(), dispOct, stFromC4);
         }
         else
         {
            ImGui::TextDisabled("%d steps, looped", steps);
         }
      }

      {
         AudioKnobRow row(4);
         row.KnobInt("steps", &n->steps, 1, NoteSequencerNode::kMaxSteps);
         DrawRateModeControls(row, &n->rateMode, &n->rateBeats, &n->rateSeconds);
         row.Knob("gate", &n->gatePercent, 1.0f, 100.0f, "%.0f%%", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   void DrawRandomNoteGeneratorBody(GraphNode& gn, RandomNoteGeneratorNode* n)
   {
      char stat[64];
      const int last = n->LastNote();
      if (last < 0)
      {
         if (n->groove > 0.001f)
            snprintf(stat, sizeof(stat), "%s in %s..%s - %.0f%% groove", MusicTime::ScaleTable(n->scale).name,
                     NoteNameList()[n->rangeLow % 12].c_str(), NoteNameList()[n->rangeHigh % 12].c_str(),
                     n->groove * 100.0f);
         else
            snprintf(stat, sizeof(stat), "%s in %s..%s", MusicTime::ScaleTable(n->scale).name,
                     NoteNameList()[n->rangeLow % 12].c_str(), NoteNameList()[n->rangeHigh % 12].c_str());
      }
      else
      {
         if (n->groove > 0.001f)
            snprintf(stat, sizeof(stat), "last: %s%d - %.0f%% groove", NoteNameList()[last % 12].c_str(),
                     last / 12 - 1, n->groove * 100.0f);
         else
            snprintf(stat, sizeof(stat), "last: %s%d", NoteNameList()[last % 12].c_str(), last / 12 - 1);
      }

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      // Row 1 (4): selector column left (scale, root), knobs right (lo, hi).
      {
         AudioKnobRow row(4);
         if (n->useGlobalScale)
            ImGui::BeginDisabled();
         row.Dropdown("scale", MusicTime::ScaleTypeList(), n->scale,
                      [n](int i) { PushUndoCheckpoint(); n->scale = i; });
         row.Dropdown("root", NoteNameList(), n->root,
                      [n](int i) { PushUndoCheckpoint(); n->root = i; });
         if (n->useGlobalScale)
            ImGui::EndDisabled();
         row.KnobInt("lo", &n->rangeLow, 0, 127, kKnobSmall);
         row.KnobInt("hi", &n->rangeHigh, 0, 127, kKnobSmall);
         row.End();
      }
      // Row 2 (4): same grid - mode/rate selector column left, knobs right.
      // DrawRateModeControls emits the mode dropdown + rate cell as two cells
      // with stable ordinals (see its header comment), so cell indices never
      // move when rate mode flips between Synced and Free.
      {
         AudioKnobRow row(4);
         DrawRateModeControls(row, &n->rateMode, &n->rateBeats, &n->rateSeconds);
         row.KnobInt("wander", &n->maxStep, 1, 12);
         row.Knob("groove", &n->groove, 0.0f, 1.0f, "%.2f", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   void DrawChorderBody(GraphNode& gn, ChorderNode* n)
   {
      char stat[64];
      snprintf(stat, sizeof(stat), "%s %s, %d-note chord", NoteNameList()[n->root].c_str(),
               MusicTime::ScaleTable(n->scale).name, n->LastChordSize());

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      {
         AudioKnobRow row(4);
         if (n->useGlobalScale)
            ImGui::BeginDisabled();
         row.Dropdown("scale", MusicTime::ScaleTypeList(), n->scale,
                      [n](int i) { PushUndoCheckpoint(); n->scale = i; });
         row.Dropdown("root", NoteNameList(), n->root,
                      [n](int i) { PushUndoCheckpoint(); n->root = i; });
         if (n->useGlobalScale)
            ImGui::EndDisabled();
         row.KnobInt("chord", &n->chordSize, 2, 6);
         row.Knob("rate", &n->rateBeats, 0.0625f, 4.0f, "%.3f beats", kKnobSmall);
         row.End();
      }
      {
         AudioKnobRow row(4);
         row.Knob("strum", &n->strumMs, 0.0f, 200.0f, "%.0fms", kKnobSmall, false, false, AudioWidgetStyle::KnobSkewStrum30);
         row.Knob("hu.time", &n->humanizeTimingMs, 0.0f, 100.0f, "%.0fms", kKnobSmall);
         row.Knob("hu.vel", &n->humanizeVelocity, 0.0f, 100.0f, "%.0f%%", kKnobSmall);
         row.Knob("harmonics", &n->upperHarmonics, 0.0f, 100.0f, "%.0f%%", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   // A row of 4 pill toggles, aligned under an AudioKnobRow(4)'s cells -
   // caption is the voice number, fixed text; the pill's fill colour is what
   // shows on/off, same convention as the Sampler's loop/rev/p-p toggles.
   void DrawNoteStackToggleRow(NoteStackNode* n, int startVoice)
   {
      const float x0 = gAudioContentX;
      const float y0 = ImGui::GetCursorScreenPos().y;
      const float cellW = gAudioContentW / 4.0f;
      const float btnW = 36.0f;
      ImGui::SetWindowFontScale(0.85f);
      const float btnH = ImGui::GetFrameHeight();
      for (int i = 0; i < 4; i++)
      {
         const int v = startVoice + i;
         const float cx = x0 + (float)i * cellW + cellW * 0.5f;
         ImGui::SetCursorScreenPos(ImVec2(cx - btnW * 0.5f, y0));
         char label[24];
         snprintf(label, sizeof(label), "%d##stackEn%d", v + 1, v);
         bool en = n->enabled[v];
         if (AudioToggleButton(label, &en, btnW))
         {
            PushUndoCheckpoint();
            n->enabled[v] = en;
         }
      }
      ImGui::SetWindowFontScale(1.0f);
      ImGui::SetCursorScreenPos(ImVec2(x0, y0 + btnH + 6.0f));
   }

   void DrawNoteStackBody(GraphNode& gn, NoteStackNode* n)
   {
      int onCount = 0;
      for (int i = 0; i < NoteStackNode::kVoices; i++)
         if (n->enabled[i])
            onCount++;

      char stat[64];
      const int lastStack = n->LastStackSize();
      if (lastStack > 0)
         snprintf(stat, sizeof(stat), "%d notes", lastStack);
      else
         snprintf(stat, sizeof(stat), "%d voice%s on", onCount, onCount == 1 ? "" : "s");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      // Row 1: Voices 1..4 (knobs on top, small toggle buttons just below)
      {
         AudioKnobRow row(4, kKnobSmall, 0.0f, false);
         for (int v = 0; v < 4; v++)
         {
            char label[24];
            snprintf(label, sizeof(label), "##stackSemi%d", v);
            if (!n->enabled[v])
               ImGui::BeginDisabled();
            row.KnobInt(label, &n->semitones[v], -24, 24);
            if (!n->enabled[v])
               ImGui::EndDisabled();
         }
         row.End();
      }
      ImGui::SetCursorScreenPos(ImVec2(gAudioContentX, ImGui::GetCursorScreenPos().y + 5.0f));
      DrawNoteStackToggleRow(n, 0);

      {
         const float w = ImGui::CalcTextSize("in - always on").x;
         const ImVec2 pos = ImGui::GetCursorScreenPos();
         ImGui::SetCursorScreenPos(ImVec2(gAudioContentX + (gAudioContentW - w) * 0.5f, pos.y + 2.0f));
         ImGui::TextColored(ImVec4(0.69f, 0.71f, 0.78f, 1.0f), "in - always on");
         ImGui::SetCursorScreenPos(ImVec2(gAudioContentX, pos.y + ImGui::GetTextLineHeightWithSpacing() + 6.0f));
      }

      // Row 2: Voices 5..8 (knobs on top, small toggle buttons just below)
      {
         AudioKnobRow row(4, kKnobSmall, 0.0f, false);
         for (int v = 4; v < 8; v++)
         {
            char label[24];
            snprintf(label, sizeof(label), "##stackSemi%d", v);
            if (!n->enabled[v])
               ImGui::BeginDisabled();
            row.KnobInt(label, &n->semitones[v], -24, 24);
            if (!n->enabled[v])
               ImGui::EndDisabled();
         }
         row.End();
      }
      ImGui::SetCursorScreenPos(ImVec2(gAudioContentX, ImGui::GetCursorScreenPos().y + 5.0f));
      DrawNoteStackToggleRow(n, 4);

      EndAudioBody();
   }


   void DrawNoteCapturerVisualizer(NoteCapturerNode* n)
   {
      bool held[128];
      n->HeldKeys(held);
      DrawMidiKeyboard(held, 48, 3);
   }

   void DrawNoteCapturerBody(GraphNode& gn, NoteCapturerNode* n)
   {
      const bool recording = n->IsRecording();
      const bool playing = n->IsPlaying();
      char stat[64];
      if (recording)
         snprintf(stat, sizeof(stat), "REC  %.1f beats", n->RecordedLengthBeats());
      else if (playing)
         snprintf(stat, sizeof(stat), "playing, %d notes", n->RecordedCount());
      else
         snprintf(stat, sizeof(stat), "%d notes recorded", n->RecordedCount());

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawNoteCapturerVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      const float btnW = (AudioFullWidth() - ImGui::GetStyle().ItemSpacing.x * 3.0f) / 4.0f;
      if (recording)
         ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.65f, 0.15f, 0.15f, 1.0f));
      if (ImGui::Button("Record", ImVec2(btnW, 0)))
      {
         if (recording) n->StopRecording();
         else n->StartRecording();
      }
      if (recording)
         ImGui::PopStyleColor();
      ImGui::SameLine();

      if (playing)
         ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.15f, 0.5f, 0.2f, 1.0f));
      ImGui::BeginDisabled(n->RecordedCount() == 0 && !playing);
      if (ImGui::Button("Play", ImVec2(btnW, 0)))
      {
         if (playing) n->StopPlayback();
         else n->StartPlayback();
      }
      ImGui::EndDisabled();
      if (playing)
         ImGui::PopStyleColor();
      ImGui::SameLine();

      if (ImGui::Button("Stop", ImVec2(btnW, 0)))
      {
         n->StopRecording();
         n->StopPlayback();
      }
      ImGui::SameLine();

      if (ImGui::Button("Clear", ImVec2(btnW, 0)))
         n->ClearRecording();

      ImGui::Dummy(ImVec2(0.0f, 2.0f));
      {
         // Same 4-cell grid as the Record/Play/Stop/Clear strip above, so
         // `loop` lands directly under Record instead of floating at the
         // body's left edge under an unrelated cell count. Small explicit
         // height (matches the Flanger/Phaser trailing-checkbox-row
         // precedent) since a lone checkbox doesn't need full knob height
         // plus a caption-line reservation.
         AudioKnobRow row(4, 20.0f, 8.0f, false);
         row.Checkbox("loop##capturerLoop", &n->loop);
         row.Dropdown("grid", MusicTime::QuantizeGridList(),
                      std::clamp(n->quantizeDiv, 0, (int)MusicTime::QuantizeGridList().size() - 1),
                      [n](int i) { PushUndoCheckpoint(); n->quantizeDiv = i; });
         row.Skip();
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   void DrawBouncingBallsVisualizer(BouncingBallsNode* n)
   {
      const float fullW = gAudioBodyW;
      // Shrunk well below the full card width (>=33% smaller than before)
      // and centered in the row, rather than filling it edge to edge.
      const float w = fullW * 0.6f;
      const float h = w; // square canvas - the shape itself needs equal aspect
      const ImVec2 rowOrigin = ImGui::GetCursorScreenPos();
      const ImVec2 origin(rowOrigin.x + (fullW - w) * 0.5f, rowOrigin.y);
      ImDrawList* dl = ImGui::GetWindowDrawList();
      const ImVec2 br(origin.x + w, origin.y + h);
      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const ImVec2 center((origin.x + br.x) * 0.5f, (origin.y + br.y) * 0.5f);
      const float scale = (w * 0.5f - 6.0f) / BouncingBallsNode::kBound;
      auto ToScreen = [&](float x, float y) { return ImVec2(center.x + x * scale, center.y - y * scale); };

      const ImU32 outlineCol = isLight ? IM_COL32(140, 150, 175, 255) : IM_COL32(150, 165, 190, 255);
      const float outlineThickness = 5.0f;
      const float b = BouncingBallsNode::kBound;
      const float triBboxCenterY = (b + -0.5f * b) * 0.5f;
      if (n->shape == BouncingBallsNode::kSquare)
      {
         dl->AddRect(ToScreen(-b, b), ToScreen(b, -b), outlineCol, 2.0f, 0, outlineThickness);
      }
      else if (n->shape == BouncingBallsNode::kTriangle)
      {
         const ImVec2 p0 = ToScreen(0.0f, b - triBboxCenterY);
         const ImVec2 p1 = ToScreen(-0.8660254f * b, -0.5f * b - triBboxCenterY);
         const ImVec2 p2 = ToScreen(0.8660254f * b, -0.5f * b - triBboxCenterY);
         dl->AddTriangle(p0, p1, p2, outlineCol, outlineThickness);
      }
      else
      {
         dl->AddCircle(center, b * scale, outlineCol, 48, outlineThickness);
      }

      float bx[BouncingBallsNode::kMaxBalls], by[BouncingBallsNode::kMaxBalls], bf[BouncingBallsNode::kMaxBalls];
      const int count = n->BallPositions(bx, by, bf);
      const float ballShiftY = (n->shape == BouncingBallsNode::kTriangle) ? triBboxCenterY : 0.0f;
      for (int i = 0; i < count; i++)
      {
         const ImVec2 p = ToScreen(bx[i], by[i] - ballShiftY);
         const float flash = std::clamp(bf[i], 0.0f, 1.0f);
         const ImU32 restCol = isLight ? IM_COL32(30, 110, 230, 245) : IM_COL32(120, 200, 255, 235);
         const ImU32 hitCol = isLight ? IM_COL32(230, 120, 20, 255) : IM_COL32(255, 190, 90, 255);
         const ImU32 col = ImGui::ColorConvertFloat4ToU32(
            ImLerp(ImGui::ColorConvertU32ToFloat4(restCol), ImGui::ColorConvertU32ToFloat4(hitCol), flash));
         dl->AddCircleFilled(p, n->ballSize * scale, col);
      }

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 4.0f);
      ImGui::SetCursorScreenPos(rowOrigin);
      ImGui::Dummy(ImVec2(fullW, h));
   }

   void DrawBouncingBallsBody(GraphNode& gn, BouncingBallsNode* n)
   {
      static const std::vector<std::string> kShapes = { "Circle", "Square", "Triangle" };
      char stat[64];
      snprintf(stat, sizeof(stat), "%s, %d balls", kShapes[std::clamp(n->shape, 0, 2)].c_str(), n->numBalls);

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawBouncingBallsVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 5.0f));

      {
         AudioKnobRow row(3);
         row.Dropdown("shape", kShapes, n->shape, [n](int i) { PushUndoCheckpoint(); n->shape = i; });
         row.KnobInt("balls", &n->numBalls, 1, BouncingBallsNode::kMaxBalls);
         row.Knob("speed", &n->ballSpeed, 0.05f, 2.0f, "%.2f", kKnobSmall);
         row.End();
      }
      {
         AudioKnobRow row(3);
         row.Knob("size", &n->ballSize, 0.02f, 0.15f, "%.2f", kKnobSmall);
         row.KnobInt("lo", &n->rangeLow, 0, 127, kKnobSmall);
         row.KnobInt("hi", &n->rangeHigh, 0, 127, kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   // Single-macro bodies below: identical standard rhythm (narrow body, one
   // centred large knob, no second row) as Note Transpose / Pitch Bend / Gate
   // / Glide / Vibrato.
   void DrawStrumBody(GraphNode& gn, NoteStrumNode* n)
   {
      char stat[48];
      snprintf(stat, sizeof(stat), "%.1f ms", n->strumMs);
      BeginAudioBody(gn.index, gn.category, kAudioNarrowWidth, stat);

      {
         AudioKnobRow row(1, kKnobLarge);
         row.Knob("strum", &n->strumMs, 0.0f, 100.0f, "%.1f ms", kKnobLarge, false, false, AudioWidgetStyle::KnobSkewStrum20);
         row.End();
      }

      EndAudioBody();
   }

   void DrawAudioToCVBody(GraphNode& gn, AudioToCVNode* n)
   {
      const float lvl = n->CurrentLevel();
      char stat[64];
      snprintf(stat, sizeof(stat), "mod %.2f", lvl);

      BeginAudioBody(gn.index, gn.category, kAudioNarrowWidth, stat);

      {
         AudioKnobRow row(2);
         row.Knob("gain", &n->gain, 0.0f, 5.0f, "%.2fx", kKnobSmall);
         static const std::vector<std::string> kModes = { "Peak", "RMS" };
         row.Dropdown("mode", kModes, n->mode,
                      [n](int i) { PushUndoCheckpoint(); n->mode = i; });
         row.End();
      }
      {
         AudioKnobRow row(2);
         row.Knob("att", &n->attackMs, 0.1f, 200.0f, "%.1f ms", kKnobSmall);
         row.Knob("rel", &n->releaseMs, 1.0f, 1000.0f, "%.0f ms", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   void DrawEnvelopeBody(GraphNode& gn, EnvelopeNode* n)
   {
      char stat[64];
      snprintf(stat, sizeof(stat), "level %.2f", n->Value01());
      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      // Same editable-ADSR panel the wavetable engines use (DrawEditableADSR /
      // DrawEnvelopePanel) rather than a bespoke read-only shape - one
      // envelope-editing look across the app instead of two that behave
      // differently. No `amount`: this node's whole output *is* the depth,
      // there's nothing else for a depth control to scale here.
      DrawEnvelopePanel("envelope  -  drag the handles", "##envAdsr", &n->attackMs, &n->decayMs,
                        &n->sustainLevel, &n->releaseMs, nullptr, 0.0f, 0.0f, "%.2f",
                        IM_COL32(150, 214, 255, 245));
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      // "in" is used only while nothing is patched into the modulator pin;
      // "threshold" is the gate line on the raw 0..1 input - rising through
      // it starts attack, falling back below it starts release (see the
      // class comment on EnvelopeNode, ModulatorNodes.h).
      AudioKnobRow row2(2);
      row2.Knob("in", &n->constantIn, 0.0f, 1.0f, "%.2f", kKnobSmall);
      row2.Knob("threshold", &n->threshold, 0.0f, 1.0f, "%.2f", kKnobSmall);
      row2.End();

      EndAudioBody();
   }

   // ---- Note to CV ---------------------------------------------------
   void DrawNoteToCVBody(GraphNode& gn, NoteToCVNode* n)
   {
      char stat[64];
      const int last = n->LastNote();
      if (last < 0)
         snprintf(stat, sizeof(stat), "%d..%d -> 0..1", n->rangeLow, n->rangeHigh);
      else
         snprintf(stat, sizeof(stat), "last: %s%d -> %.2f", NoteNameList()[last % 12].c_str(), last / 12 - 1,
                  n->Value01());

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      AudioKnobRow row(3);
      row.KnobInt("range lo", &n->rangeLow, 0, 126);
      row.KnobInt("range hi", &n->rangeHigh, 1, 127);
      row.Knob("glide", &n->glideMs, 0.0f, 500.0f, "%.0f ms", kKnobLarge, false, false, AudioWidgetStyle::KnobSkewGlide100);
      row.End();

      EndAudioBody();
   }

   // ---- Audio Filter -----------------------------------------------------
   // Cached per-node response curve: the underlying MagnitudeDb sweep is a
   // settled-sine measurement (AudioFilterKernel.h) that runs an actual
   // settle-then-measure simulation of the filter primitive per point (up to
   // ~8000 simulated samples each) - cheap for a one-off recompute, but not
   // free across 160 points every single ImGui frame while freq/Q/gain are
   // being dragged (up to ~1.28M simulated samples/frame). Recomputed only
   // when the signature (everything it depends on) actually changed (per
   // audio-node-ui-system.md §3f's "computed main-thread ... never by
   // calling into the live AudioNode" - this recomputes from a *scratch*
   // Biquad/TptSvf, same as the kernel's own PushParams, not the running
   // one) - AND, while a drag is actively changing the signature every
   // frame, throttled to at most once per kFilterCurveThrottleSec so a drag
   // doesn't force a full recompute at UI frame rate. The heuristic for "a
   // drag is happening" is deliberately the same one the task that added
   // this used: the signature changed on this exact frame AND the mouse
   // button is currently held (a typed edit or a single modulation step
   // changes the signature without the button held, and gets an immediate,
   // un-throttled, full-resolution recompute - so the *final* curve after
   // any change, drag or not, is always full 160-point resolution).
   struct FilterCurveCache
   {
      std::vector<float> curveDb; // one entry per x pixel column sampled
      std::vector<float> signature;    // signature that produced curveDb
      std::vector<float> lastSeenSignature; // signature observed last frame
      double lastRecomputeTime = -1.0;
      bool dragIsQ = false; // which handle the current drag (if any) is grabbing
   };
   std::map<int, FilterCurveCache> gFilterCurveCache;
   // Throttling *how often* the recompute fires (below) caps it at ~12.5Hz,
   // but that alone isn't enough: a full 160-point AudioFilterDsp::MagnitudeDb
   // sweep is a real settle-then-measure simulation per point (up to ~8000
   // samples each, each involving a sin() call) and measures ~10-15ms on its
   // own at Q=18/48kHz - comparable to or larger than an entire 60fps frame
   // budget (16.6ms), so even a throttled recompute still stalls the frame it
   // lands on. kFilterCurveDragPoints cuts the *cost* of each recompute by
   // dropping the point count while a drag is live (measured ~3-5x cheaper at
   // 48 points) - full kFilterCurveFullPoints resolution always returns the
   // instant the drag ends.
   const double kFilterCurveThrottleSec = 0.08; // ~12.5 Hz cap on the full recompute while dragging
   const int kFilterCurveDragPoints = 48;
   const int kFilterCurveFullPoints = 160;

   const float kFilterVizMinHz = 20.0f;
   const float kFilterVizMaxHz = 20000.0f;
   const float kFilterVizMinDb = -24.0f;
   const float kFilterVizMaxDb = 24.0f;

   float FilterVizFreqToX(float hz, float x0, float w)
   {
      const float t = (logf(std::max(1.0f, hz)) - logf(kFilterVizMinHz)) /
                      (logf(kFilterVizMaxHz) - logf(kFilterVizMinHz));
      return x0 + std::clamp(t, 0.0f, 1.0f) * w;
   }

   float FilterVizXToFreq(float x, float x0, float w)
   {
      const float t = std::clamp((x - x0) / std::max(1.0f, w), 0.0f, 1.0f);
      return kFilterVizMinHz * powf(kFilterVizMaxHz / kFilterVizMinHz, t);
   }

   float FilterVizDbToY(float db, float y0, float h)
   {
      const float t = (db - kFilterVizMinDb) / (kFilterVizMaxDb - kFilterVizMinDb);
      return y0 + h - std::clamp(t, 0.0f, 1.0f) * h;
   }

   float FilterVizYToDb(float y, float y0, float h)
   {
      const float t = std::clamp((y0 + h - y) / h, 0.0f, 1.0f);
      return kFilterVizMinDb + t * (kFilterVizMaxDb - kFilterVizMinDb);
   }

   // Shared graticule for Audio Filter and EQ - decade-anchored frequency
   // ticks plus dB ticks, both labeled. The two callers were previously
   // drawing identical unlabeled tick loops (confirmed-safe dedup).
   void DrawFilterGraticule(ImDrawList* dl, ImVec2 origin, float w, float h)
   {
      static const float kFreqTicks[] = { 20.0f, 50.0f, 100.0f, 200.0f, 500.0f, 1000.0f,
                                          2000.0f, 5000.0f, 10000.0f, 20000.0f };
      const float textY = origin.y + h - ImGui::GetTextLineHeight() - 2.0f;
      for (float f : kFreqTicks)
      {
         const bool isEdge = (f <= kFilterVizMinHz || f >= kFilterVizMaxHz);
         const bool isDecadeAnchor = (f == 100.0f || f == 1000.0f || f == 10000.0f);
         const float x = FilterVizFreqToX(f, origin.x, w);
         if (!isEdge)
            dl->AddLine(ImVec2(x, origin.y), ImVec2(x, origin.y + h),
                        isDecadeAnchor ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);

         char buf[8];
         if (f < 1000.0f)
            snprintf(buf, sizeof(buf), "%.0f", f);
         else
            snprintf(buf, sizeof(buf), "%.0fk", f / 1000.0f);

         if (f <= kFilterVizMinHz)
            dl->AddText(ImVec2(origin.x + 3.0f, textY), ScopeTextCol(), buf);
         else if (f >= kFilterVizMaxHz)
            dl->AddText(ImVec2(origin.x + w - 3.0f - ImGui::CalcTextSize(buf).x, textY), ScopeTextCol(), buf);
         else
            dl->AddText(ImVec2(x - ImGui::CalcTextSize(buf).x * 0.5f, textY), ScopeTextCol(), buf);
      }

      static const float kDbTicks[] = { -18.0f, -12.0f, -6.0f, 0.0f, 6.0f, 12.0f, 18.0f };
      static const bool kDbLabeled[] = { true, true, false, true, false, true, true };
      for (int i = 0; i < 7; i++)
      {
         const float db = kDbTicks[i];
         const float y = FilterVizDbToY(db, origin.y, h);
         dl->AddLine(ImVec2(origin.x, y), ImVec2(origin.x + w, y),
                     db == 0.0f ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
         if (kDbLabeled[i])
         {
            char buf[8];
            if (db == 0.0f)
               snprintf(buf, sizeof(buf), "0");
            else
               snprintf(buf, sizeof(buf), "%+.0f", db);
            dl->AddText(ImVec2(origin.x + 3.0f, y - (db == 0.0f ? 14.0f : 1.0f)), ScopeTextCol(), buf);
         }
      }
   }

   // Full-width log-frequency response curve with a draggable handle per
   // band - the reason Audio Filter is built first (§1.1): X = freq,
   // Y = gain, scroll = Q, double-click = enable/disable. This *is* the
   // Tier 1 control surface's picture, per audio-node-ui-system.md §3g.
   void DrawAudioFilterVisualizer(AudioEffectNode* n, double sampleRate)
   {
      const float w = gAudioBodyW;
      const float h = 190.0f; // fills the space the old per-band strip used to occupy
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      ImGui::InvisibleButton("##filterCurve", ImVec2(w, h));
      const bool hovered = ImGui::IsItemHovered();
      const bool active = ImGui::IsItemActive();
      if (ImGui::IsItemActivated())
         PushUndoCheckpoint();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      // Graticule that keeps this from reading as blank at rest (§3f).
      DrawFilterGraticule(dl, origin, w, h);

      const float type = n->Param("type");
      const float freq = n->Param("freq");
      const float q = n->Param("q");
      const float gain = n->Param("gain");

      std::vector<float> sig{ (float)sampleRate, type, freq, q, gain };
      FilterCurveCache& cache = gFilterCurveCache[gCurrentNodeIndex];

      // Throttle the full recompute while a drag is actively changing the
      // signature every frame - see the FilterCurveCache comment above for
      // the full reasoning. `sigChanged` catches the drag case;
      // `cache.signature != sig` is what actually needs a recompute (true
      // the first frame after any change, drag or not).
      const bool sigChanged = (cache.lastSeenSignature != sig);
      cache.lastSeenSignature = sig;
      const bool dragging = sigChanged && ImGui::IsMouseDown(ImGuiMouseButton_Left);
      const double now = ImGui::GetTime();
      const bool throttled = dragging && cache.lastRecomputeTime >= 0.0 &&
                             (now - cache.lastRecomputeTime) < kFilterCurveThrottleSec;
      // Coarser while a drag is live (see kFilterCurveDragPoints comment
      // above); the mouse-up frame has dragging=false, so it always recomputes
      // at full resolution the instant the drag ends.
      const int kNumPoints = dragging ? kFilterCurveDragPoints : kFilterCurveFullPoints;
      if (cache.signature != sig && !throttled)
      {
         cache.signature = sig;
         cache.lastRecomputeTime = now;
         cache.curveDb.resize(kNumPoints);
         for (int i = 0; i < kNumPoints; i++)
         {
            const float x = origin.x + (float)i * (w / (float)(kNumPoints - 1));
            const float f = FilterVizXToFreq(x, origin.x, w);
            cache.curveDb[i] = AudioFilterDsp::MagnitudeDb((int)(type + 0.5f), freq, q, gain, f, sampleRate);
         }
      }

      // The base curve and its handles below always reflect the actual
      // knob-set freq/Q/gain and never move on their own - a curve that
      // silently shifts out from under a value the knobs still show is a P9
      // truthfulness violation. `cache.curveDb.size()` (not `kNumPoints`,
      // which reflects *this frame's* drag state and can be one frame stale
      // relative to the cache on the exact mouse-release frame) is the
      // source of truth for how many points are actually cached.
      const int cachedPoints = (int)cache.curveDb.size();
      dl->PathClear();
      for (int i = 0; i < cachedPoints; i++)
      {
         const float x = origin.x + (float)i * (w / (float)(cachedPoints - 1));
         const float y = FilterVizDbToY(cache.curveDb[i], origin.y, h);
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      // Live LFO sweep indicator (envAmount != 0): a second curve, in yellow,
      // overlaid on top of the static base curve above - it never replaces
      // or moves the base curve/handles, purely an animated readout of where
      // the internal LFO currently has the cutoff swept to. Reuses the same
      // cached curveDb array (translated in x), so this costs nothing extra
      // in MagnitudeDb calls - octaves of cutoff shift are a constant
      // pixel-space offset along the log-frequency axis, since the response
      // of these filter types depends only on the ratio of the eval
      // frequency to the cutoff, not the cutoff's absolute position (exact
      // for SVF LP/HP/BP/notch, a close approximation for the shelf/peak
      // biquad types this close to Nyquist). `lfoOut` is read from the
      // kernel's own audio-thread LFO (AudioFilterKernel::mLfoMeter) via the
      // existing ExtraMeterValue MeterRing readback, same discipline as
      // Dynamics' GR-bar dot - no new cross-thread mechanism.
      const float envAmount = n->Param("envAmount");
      const float lfoOut = envAmount != 0.0f ? std::clamp(n->ExtraMeterValue(0), -1.0f, 1.0f) : 0.0f;
      const float totalOctaves = envAmount * lfoOut * 4.0f;
      const float pixelsPerOctave = w * logf(2.0f) / (logf(kFilterVizMaxHz) - logf(kFilterVizMinHz));
      const float deltaX = totalOctaves * pixelsPerOctave;
      if (envAmount != 0.0f)
      {
         dl->PathClear();
         for (int i = 0; i < cachedPoints; i++)
         {
            const float x = origin.x + (float)i * (w / (float)(cachedPoints - 1)) + deltaX;
            const float y = FilterVizDbToY(cache.curveDb[i], origin.y, h);
            dl->PathLineTo(ImVec2(x, y));
         }
         dl->PathStroke(IM_COL32(255, 205, 60, 210), 0, 1.5f);
      }

      // Two handles sharing the single ##filterCurve button above - the
      // round one sets freq/gain, the diamond sets Q. Q used to ride the
      // scroll wheel, but that gesture is also how the canvas itself zooms
      // - scrolling to zoom while the cursor happened to be over this
      // viewport silently dragged Q along with it, with no relation to the
      // real Q knob. A second real ImGui item drawn on top of the first
      // (to make Q separately clickable) turned out to disturb the layout
      // cursor for the knob row drawn after this function, breaking drag on
      // both handles - so instead this stays one button, and on click we
      // just decide (by proximity) which handle that particular drag grabs,
      // remembering the choice for the rest of the drag.
      const float hx = FilterVizFreqToX(freq, origin.x, w);
      const float hy = FilterVizDbToY(AudioFilterDsp::UsesGain((int)(type + 0.5f)) ? gain : 0.0f, origin.y, h);

      const float qT = (logf(std::max(0.1f, q)) - logf(0.1f)) / (logf(18.0f) - logf(0.1f));
      const float qx = std::clamp(hx + 16.0f, origin.x + 8.0f, br.x - 8.0f);
      const float qy = origin.y + h - std::clamp(qT, 0.0f, 1.0f) * h;

      if (ImGui::IsItemActivated())
      {
         const ImVec2 m = ImGui::GetIO().MousePos;
         const float dMain = (m.x - hx) * (m.x - hx) + (m.y - hy) * (m.y - hy);
         const float dQ = (m.x - qx) * (m.x - qx) + (m.y - qy) * (m.y - qy);
         cache.dragIsQ = dQ < dMain;
      }

      const bool isNear = hovered || active;

      if (active && cache.dragIsQ)
      {
         const float my = ImGui::GetIO().MousePos.y;
         const float t = std::clamp((origin.y + h - my) / h, 0.0f, 1.0f);
         *n->ParamPtr("q") = std::clamp(0.1f * powf(18.0f / 0.1f, t), 0.1f, 18.0f);
      }
      else if (active)
      {
         const ImVec2 m = ImGui::GetIO().MousePos;
         *n->ParamPtr("freq") = std::clamp(FilterVizXToFreq(m.x, origin.x, w), kFilterVizMinHz, kFilterVizMaxHz);
         if (AudioFilterDsp::UsesGain((int)(type + 0.5f)))
            *n->ParamPtr("gain") = FilterVizYToDb(m.y, origin.y, h);
      }

      // Handle stays at the real (non-LFO-shifted) freq/gain - it's the
      // knob-set value, and only the yellow overlay above should visually
      // sweep.
      const bool mainNear = isNear && !(active && cache.dragIsQ);
      dl->AddCircleFilled(ImVec2(hx, hy), mainNear ? 5.0f : 3.6f, IM_COL32(235, 245, 255, 255), 12);
      dl->AddCircle(ImVec2(hx, hy), mainNear ? 5.0f : 3.6f, IM_COL32(20, 24, 32, 220), 12, 1.5f);

      // Diamond handle for Q, offset beside the main dot so both stay
      // visually distinct.
      const bool qNear = isNear && (!active || cache.dragIsQ);
      const float qr = qNear ? 5.5f : 4.0f;
      const ImVec2 qPts[4] = { ImVec2(qx, qy - qr), ImVec2(qx + qr, qy), ImVec2(qx, qy + qr), ImVec2(qx - qr, qy) };
      dl->AddConvexPolyFilled(qPts, 4, IM_COL32(255, 205, 120, 255));
      dl->AddPolyline(qPts, 4, IM_COL32(20, 24, 32, 220), ImDrawFlags_Closed, 1.5f);

      dl->PopClipRect();
      dl->AddRect(origin, br, hovered ? (isLight ? IM_COL32(50, 120, 220, 255) : IM_COL32(110, 140, 180, 255))
                                      : ScopeBorderCol(), 3.0f);

      if (isNear)
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "%.0f Hz  %+.1f dB  Q %.2f", freq, gain, q);
         SetAudioReadout("filter", buf);
      }
      // No trailing Dummy here: the InvisibleButton above already reserved
      // this (w, h) layout space - a second Dummy of the same size would
      // double-reserve it and leave a blank gap the height of the graph
      // between it and whatever's drawn next.
   }

   // Forward declaration: the shared sync/rate-mode cell pair Chorus/
   // Flanger/Phaser/Tremolo all use is defined further down (with the rest
   // of their shared helpers), but Audio Filter's own body is defined here,
   // earlier in the file, and now uses it too for its "env" LFO's rate.
   // Default rateLo/rateHi live only on this first declaration - a default
   // argument can only be specified once across all declarations seen by
   // the translation unit, so the real definition below no longer repeats
   // them.
   void AddRateModeCells(AudioKnobRow& row, AudioEffectNode* n, const char* syncLabel,
                         float rateLo = 0.02f, float rateHi = 5.0f);

   void DrawAudioFilterBody(GraphNode& gn, AudioEffectNode* n)
   {
      const int type = (int)(n->Param("type") + 0.5f);
      const float freq = n->Param("freq");
      const float q = n->Param("q");

      char stat[80];
      snprintf(stat, sizeof(stat), "%s - %.1f kHz - Q %.2f", AudioFilterDsp::TypeName(type),
               freq / 1000.0f, q);

      const double sampleRate = AudioEngine::Instance().SampleRate() > 0.0
                                   ? AudioEngine::Instance().SampleRate()
                                   : 44100.0;

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawAudioFilterVisualizer(n, sampleRate);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(4);
         row.Dropdown("type", AudioFilterDsp::TypeList(), type, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("type") = (float)i;
         });
         row.Knob("freq", n->ParamPtr("freq"), 20.0f, 20000.0f, "%.0f Hz", kKnobLarge);
         row.Knob("Q", n->ParamPtr("q"), 0.1f, 18.0f, "%.2f", kKnobLarge);

         const bool gainLive = AudioFilterDsp::UsesGain(type);
         if (!gainLive)
            ImGui::BeginDisabled();
         row.Knob("gain", n->ParamPtr("gain"), -24.0f, 24.0f, "%.1f dB", kKnobLarge);
         if (!gainLive)
            ImGui::EndDisabled();
         row.End();
      }

      BeginAudioSection("output");
      {
         // 4 cells: selector column left (sync v, rate), knobs right
         // (env, mix) - mix stays bottom-right (P4). `row.index` is set
         // explicitly before each call so the *visual* cell a control lands
         // in can differ from its *draw order* - mix and env are still
         // called first and second, exactly as before "output gain" was
         // removed (it's redundant with the filter's own `gain` knob above),
         // so their gParamCounter ordinals stay in the same relative order
         // to each other and to sync/rate. Deleting "output gain"'s knob
         // outright (not just repositioning it) does still shift every
         // later-drawn param's ordinal down by one relative to old patches -
         // unavoidable when removing a param's control entirely, same
         // reasoning DrawChorusBody uses for its near-identical layout
         // problem.
         AudioKnobRow row(4);
         row.index = 3;
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 2;
         row.Knob("env", n->ParamPtr("envAmount"), -1.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 0;
         AddRateModeCells(row, n, "sync to tempo##filterSync");
         row.End();
      }
      EndAudioSection();

      EndAudioBody();
   }

   // ---- EQ -------------------------------------------------------------
   // Five fixed bands, always present - docs/plans/audio/eq-node-prompt.md.
   // Reuses Audio Filter's log-frequency graticule/mapping helpers verbatim
   // (FilterVizFreqToX/XToFreq/DbToY/YToDb, kFilterViz*) rather than defining
   // a second copy - both nodes share the same 20 Hz-20 kHz / +-24 dB frame.
   struct EqCurveCache
   {
      std::vector<float> curveDb;       // composite, one entry per x column
      std::vector<float> bandCurveDb[5]; // per-band, only enabled ones drawn
      std::vector<float> signature;
      int dragBand = -1;
      bool dragIsQ = false;
      bool dragInert = false; // this gesture is a select-only click or a double-click toggle
   };
   std::map<int, EqCurveCache> gEqCurveCache;

   static const char* const kEqTypeParam[5] = { "band1Type", "band2Type", "band3Type", "band4Type", "band5Type" };
   static const char* const kEqFreqParam[5] = { "band1Freq", "band2Freq", "band3Freq", "band4Freq", "band5Freq" };
   static const char* const kEqQParam[5] = { "band1Q", "band2Q", "band3Q", "band4Q", "band5Q" };
   static const char* const kEqGainParam[5] = { "band1Gain", "band2Gain", "band3Gain", "band4Gain", "band5Gain" };
   static const char* const kEqOnParam[5] = { "band1On", "band2On", "band3On", "band4On", "band5On" };

   struct EqBandValues
   {
      int type;
      float freq, q, gain;
      bool on;
   };

   void ReadEqBands(AudioEffectNode* n, EqBandValues bands[5])
   {
      for (int b = 0; b < 5; b++)
      {
         bands[b].type = std::clamp((int)(n->Param(kEqTypeParam[b]) + 0.5f), 0, EqDsp::kNumBandTypes - 1);
         bands[b].freq = n->Param(kEqFreqParam[b]);
         bands[b].q = n->Param(kEqQParam[b]);
         bands[b].gain = n->Param(kEqGainParam[b]);
         bands[b].on = n->Param(kEqOnParam[b]) >= 0.5f;
      }
   }

   // Live incoming-signal spectrum drawn behind the EQ curve (the thing
   // FabFilter Pro-Q shows and this visualizer didn't). Taps the post-mix
   // mono ring AudioEffectRuntime now writes every audio block
   // (AudioEffectNode.cpp's mSpectrumRing) and runs it through the same
   // Hann-window + Radix2FFT recipe AudioColorRampNode::ProcessAudioFFT
   // already uses (AudioColorRampNode.cpp) - just plotted against this
   // visualizer's own log-frequency axis instead of feeding a color ramp.
   struct EqSpectrumState
   {
      std::vector<float> window = std::vector<float>(1024, 0.0f);
      std::vector<float> smoothed = std::vector<float>(512, 0.0f);
   };
   std::map<int, EqSpectrumState> gEqSpectrumCache;

   // Spectrum level has its own dB scale, independent of the +-24 dB gain
   // axis the response curve uses - same relationship as Pro-Q, where the
   // analyzer trace and the EQ curve share an x-axis but not a y-axis.
   const float kEqSpectrumFloorDb = -72.0f;
   const float kEqSpectrumCeilDb = 0.0f;

   float EqSpectrumDbToY(float db, float y0, float h)
   {
      const float t = (db - kEqSpectrumFloorDb) / (kEqSpectrumCeilDb - kEqSpectrumFloorDb);
      return y0 + h - std::clamp(t, 0.0f, 1.0f) * h;
   }

   void UpdateEqSpectrum(AudioEffectNode* n, EqSpectrumState& st)
   {
      const int winSize = 1024;
      float tempBuf[1024];
      const int readCount = n->ReadSpectrumSamples(tempBuf, winSize);
      if (readCount > 0)
      {
         if (readCount >= winSize)
         {
            st.window.assign(tempBuf + (readCount - winSize), tempBuf + readCount);
         }
         else
         {
            const int keep = winSize - readCount;
            std::copy(st.window.begin() + readCount, st.window.end(), st.window.begin());
            std::copy(tempBuf, tempBuf + readCount, st.window.begin() + keep);
         }
      }

      float re[1024];
      float im[1024];
      for (int i = 0; i < winSize; i++)
      {
         const float wnd = 0.5f * (1.0f - cosf(2.0f * 3.14159265358979323846f * (float)i / (float)(winSize - 1)));
         re[i] = st.window[i] * wnd;
         im[i] = 0.0f;
      }
      WaveTerrainDsp::Radix2FFT::Instance().Forward(re, im);

      for (int i = 1; i < 512; i++)
      {
         const float mag = sqrtf(re[i] * re[i] + im[i] * im[i]) * (2.0f / (float)winSize);
         st.smoothed[i] = st.smoothed[i] * 0.7f + mag * 0.3f;
      }
   }

   void DrawEqSpectrum(ImDrawList* dl, ImVec2 origin, float w, float h, double sampleRate, const EqSpectrumState& st,
                       bool isLight)
   {
      const float binWidth = (float)(sampleRate > 0.0 ? sampleRate : 44100.0) / 1024.0f;
      const float baselineY = origin.y + h;
      const ImU32 fillCol = isLight ? IM_COL32(70, 90, 120, 40) : IM_COL32(210, 220, 235, 40);
      const ImU32 lineCol = isLight ? IM_COL32(70, 90, 120, 130) : IM_COL32(210, 220, 235, 130);

      float prevX = FilterVizFreqToX(binWidth, origin.x, w);
      float prevY = EqSpectrumDbToY(20.0f * log10f(std::max(st.smoothed[1], 1.0e-6f)), origin.y, h);
      dl->PathClear();
      dl->PathLineTo(ImVec2(prevX, prevY));
      for (int i = 2; i < 512; i++)
      {
         const float freq = (float)i * binWidth;
         const float db = 20.0f * log10f(std::max(st.smoothed[i], 1.0e-6f));
         const float x = FilterVizFreqToX(freq, origin.x, w);
         const float y = EqSpectrumDbToY(db, origin.y, h);
         dl->AddQuadFilled(ImVec2(prevX, baselineY), ImVec2(x, baselineY), ImVec2(x, y), ImVec2(prevX, prevY), fillCol);
         dl->PathLineTo(ImVec2(x, y));
         prevX = x;
         prevY = y;
      }
      dl->PathStroke(lineCol, 0, 1.2f);
   }

   void DrawEqVisualizer(AudioEffectNode* n, double sampleRate)
   {
      const float w = gAudioBodyW;
      const float h = 190.0f;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      gEqTestRect = ImVec4(origin.x, origin.y, br.x, br.y);

      ImGui::InvisibleButton("##eqCurve", ImVec2(w, h));
      const bool hovered = ImGui::IsItemHovered();
      const bool active = ImGui::IsItemActive();
      if (ImGui::IsItemActivated())
         PushUndoCheckpoint();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      DrawFilterGraticule(dl, origin, w, h);

      EqSpectrumState& specState = gEqSpectrumCache[gCurrentNodeIndex];
      UpdateEqSpectrum(n, specState);
      DrawEqSpectrum(dl, origin, w, h, sampleRate, specState, isLight);

      EqBandValues bands[5];
      ReadEqBands(n, bands);
      int selected = std::clamp((int)(n->Param("selectedBand") + 0.5f), 0, 4);

      std::vector<float> sig;
      sig.reserve(26);
      sig.push_back((float)sampleRate);
      for (int b = 0; b < 5; b++)
      {
         sig.push_back((float)bands[b].type);
         sig.push_back(bands[b].freq);
         sig.push_back(bands[b].q);
         sig.push_back(bands[b].gain);
         sig.push_back(bands[b].on ? 1.0f : 0.0f);
      }

      EqCurveCache& cache = gEqCurveCache[gCurrentNodeIndex];
      const int kNumPoints = 160;
      if (cache.signature != sig)
      {
         cache.signature = sig;
         cache.curveDb.resize(kNumPoints);
         for (int b = 0; b < 5; b++)
            cache.bandCurveDb[b].resize(kNumPoints);
         for (int i = 0; i < kNumPoints; i++)
         {
            const float x = origin.x + (float)i * (w / (float)(kNumPoints - 1));
            const float f = FilterVizXToFreq(x, origin.x, w);
            float composite = 0.0f;
            for (int b = 0; b < 5; b++)
            {
               const float bandDb =
                  EqDsp::BandMagnitudeDb(bands[b].type, bands[b].freq, bands[b].q, bands[b].gain,
                                          bands[b].on, f, sampleRate);
               cache.bandCurveDb[b][i] = bandDb;
               composite += bandDb;
            }
            cache.curveDb[i] = composite;
         }
      }

      // Per-band curves at low alpha, only for enabled bands - a disabled
      // band draws a hollow dot and no curve (§3f, "never blank" cuts both
      // ways: absence is shown, not hidden).
      for (int b = 0; b < 5; b++)
      {
         if (!bands[b].on)
            continue;
         dl->PathClear();
         for (int i = 0; i < kNumPoints; i++)
         {
            const float x = origin.x + (float)i * (w / (float)(kNumPoints - 1));
            const float y = FilterVizDbToY(cache.bandCurveDb[b][i], origin.y, h);
            dl->PathLineTo(ImVec2(x, y));
         }
         dl->PathStroke(IM_COL32(150, 214, 255, 60), 0, 1.0f);
      }

      // Composite curve, bright, with a soft fill down to the 0 dB baseline -
      // built from per-segment quads rather than AddConvexPolyFilled, which
      // assumes convexity a response curve doesn't guarantee.
      const float baselineY = FilterVizDbToY(0.0f, origin.y, h);
      for (int i = 0; i + 1 < kNumPoints; i++)
      {
         const float x0 = origin.x + (float)i * (w / (float)(kNumPoints - 1));
         const float x1 = origin.x + (float)(i + 1) * (w / (float)(kNumPoints - 1));
         const float y0 = FilterVizDbToY(cache.curveDb[i], origin.y, h);
         const float y1 = FilterVizDbToY(cache.curveDb[i + 1], origin.y, h);
         dl->AddQuadFilled(ImVec2(x0, baselineY), ImVec2(x1, baselineY), ImVec2(x1, y1), ImVec2(x0, y0),
                           isLight ? IM_COL32(30, 110, 230, 30) : IM_COL32(150, 214, 255, 22));
      }

      // Persistent selected-band caption - unlike the hover readout below,
      // this is visible at rest so the user always knows what's selected.
      {
         char freqBuf[16];
         if (bands[selected].freq < 1000.0f)
            snprintf(freqBuf, sizeof(freqBuf), "%.0f Hz", bands[selected].freq);
         else
            snprintf(freqBuf, sizeof(freqBuf), "%.2f kHz", bands[selected].freq / 1000.0f);
         char capBuf[80];
         snprintf(capBuf, sizeof(capBuf), "band %d \xC2\xB7 %s \xC2\xB7 %+.1f dB \xC2\xB7 Q %.2f", selected + 1,
                  freqBuf, bands[selected].gain, bands[selected].q);
         dl->AddText(ImVec2(origin.x + 6.0f, origin.y + 4.0f), ScopeTextCol(), capBuf);
      }

      dl->PathClear();
      for (int i = 0; i < kNumPoints; i++)
      {
         const float x = origin.x + (float)i * (w / (float)(kNumPoints - 1));
         const float y = FilterVizDbToY(cache.curveDb[i], origin.y, h);
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      // Handle positions for every band - one dot (freq/gain) and one
      // diamond (Q) each, sharing the single ##eqCurve button above for the
      // same reason Audio Filter's do (a second real ImGui item per handle
      // disturbs the layout cursor for the knob row drawn afterward).
      float hx[5], hy[5], qx[5], qy[5];
      for (int b = 0; b < 5; b++)
      {
         hx[b] = FilterVizFreqToX(bands[b].freq, origin.x, w);
         hy[b] = FilterVizDbToY(EqDsp::UsesGain(bands[b].type) ? bands[b].gain : 0.0f, origin.y, h);
         const float qT = (logf(std::max(0.1f, bands[b].q)) - logf(0.1f)) / (logf(18.0f) - logf(0.1f));
         qx[b] = std::clamp(hx[b] + 16.0f, origin.x + 8.0f, br.x - 8.0f);
         qy[b] = origin.y + h - std::clamp(qT, 0.0f, 1.0f) * h;
      }

      if (ImGui::IsItemActivated())
      {
         const ImVec2 m = ImGui::GetIO().MousePos;
         float bestDist2 = 1.0e30f;
         int bestBand = selected;
         bool bestIsQ = false;
         float bestDotDist2 = 1.0e30f;
         int bestDotBand = selected;
         for (int b = 0; b < 5; b++)
         {
            const float dDot = (m.x - hx[b]) * (m.x - hx[b]) + (m.y - hy[b]) * (m.y - hy[b]);
            const float dQ = (m.x - qx[b]) * (m.x - qx[b]) + (m.y - qy[b]) * (m.y - qy[b]);
            if (dDot < bestDist2) { bestDist2 = dDot; bestBand = b; bestIsQ = false; }
            if (dQ < bestDist2) { bestDist2 = dQ; bestBand = b; bestIsQ = true; }
            if (dDot < bestDotDist2) { bestDotDist2 = dDot; bestDotBand = b; }
         }
         const float kHandleGrabRadius2 = 20.0f * 20.0f;
         cache.dragInert = false;
         if (bestDist2 <= kHandleGrabRadius2)
         {
            cache.dragBand = bestBand;
            cache.dragIsQ = bestIsQ;
         }
         else
         {
            // Click landed away from every handle - select the nearest band
            // by its dot, but this gesture does not move anything.
            cache.dragBand = bestDotBand;
            cache.dragIsQ = false;
            cache.dragInert = true;
         }
         *n->ParamPtr("selectedBand") = (float)cache.dragBand;
         selected = cache.dragBand;
      }

      // Double-click a band's dot toggles its bandOn, and cancels this
      // gesture's drag so the toggle doesn't also nudge freq/gain.
      if (hovered && ImGui::IsMouseDoubleClicked(0))
      {
         const ImVec2 m = ImGui::GetIO().MousePos;
         float bestDotDist2 = 1.0e30f;
         int bestDotBand = -1;
         for (int b = 0; b < 5; b++)
         {
            const float dDot = (m.x - hx[b]) * (m.x - hx[b]) + (m.y - hy[b]) * (m.y - hy[b]);
            if (dDot < bestDotDist2) { bestDotDist2 = dDot; bestDotBand = b; }
         }
         const float kToggleRadius2 = 20.0f * 20.0f;
         if (bestDotBand >= 0 && bestDotDist2 <= kToggleRadius2)
         {
            *n->ParamPtr(kEqOnParam[bestDotBand]) = bands[bestDotBand].on ? 0.0f : 1.0f;
            cache.dragInert = true;
         }
      }

      const int dragBand = std::clamp(cache.dragBand < 0 ? selected : cache.dragBand, 0, 4);
      if (active && !cache.dragInert)
      {
         if (cache.dragIsQ)
         {
            const float my = ImGui::GetIO().MousePos.y;
            const float t = std::clamp((origin.y + h - my) / h, 0.0f, 1.0f);
            *n->ParamPtr(kEqQParam[dragBand]) = std::clamp(0.1f * powf(18.0f / 0.1f, t), 0.1f, 18.0f);
         }
         else
         {
            const ImVec2 m = ImGui::GetIO().MousePos;
            *n->ParamPtr(kEqFreqParam[dragBand]) =
               std::clamp(FilterVizXToFreq(m.x, origin.x, w), kFilterVizMinHz, kFilterVizMaxHz);
            if (EqDsp::UsesGain(bands[dragBand].type))
               *n->ParamPtr(kEqGainParam[dragBand]) = std::clamp(FilterVizYToDb(m.y, origin.y, h), -24.0f, 24.0f);
         }
      }

      // Draw every non-selected band's handles first, then the selected
      // band's larger and last, so it is never occluded by a neighbour.
      for (int pass = 0; pass < 2; pass++)
      {
         for (int b = 0; b < 5; b++)
         {
            const bool isSelected = (b == selected);
            if ((pass == 0) == isSelected)
               continue;

            const bool isDragTarget = active && !cache.dragInert && dragBand == b;
            const bool qActiveHere = isDragTarget && cache.dragIsQ;
            const bool dotActiveHere = isDragTarget && !cache.dragIsQ;

            const float dotR = isSelected ? (dotActiveHere ? 6.5f : 4.8f) : (dotActiveHere ? 5.0f : 3.2f);
            if (bands[b].on)
            {
               dl->AddCircleFilled(ImVec2(hx[b], hy[b]), dotR, IM_COL32(235, 245, 255, isSelected ? 255 : 170), 12);
            }
            else
            {
               dl->AddCircle(ImVec2(hx[b], hy[b]), dotR, IM_COL32(235, 245, 255, isSelected ? 220 : 120), 12, 1.5f);
            }
            dl->AddCircle(ImVec2(hx[b], hy[b]), dotR, IM_COL32(20, 24, 32, 220), 12, 1.2f);

            const float qr = isSelected ? (qActiveHere ? 6.5f : 5.0f) : (qActiveHere ? 5.5f : 3.6f);
            const ImU32 qCol = isSelected ? IM_COL32(255, 205, 120, 255) : IM_COL32(255, 205, 120, 150);
            const ImVec2 qPts[4] = { ImVec2(qx[b], qy[b] - qr), ImVec2(qx[b] + qr, qy[b]),
                                     ImVec2(qx[b], qy[b] + qr), ImVec2(qx[b] - qr, qy[b]) };
            dl->AddConvexPolyFilled(qPts, 4, qCol);
            dl->AddPolyline(qPts, 4, IM_COL32(20, 24, 32, 220), ImDrawFlags_Closed, 1.2f);
         }
      }

      dl->PopClipRect();
      dl->AddRect(origin, br, hovered ? (isLight ? IM_COL32(50, 120, 220, 255) : IM_COL32(110, 140, 180, 255))
                                      : ScopeBorderCol(), 3.0f);

      if (hovered || active)
      {
         const int b = dragBand;
         char buf[80];
         snprintf(buf, sizeof(buf), "band %d  %.0f Hz  %+.1f dB  Q %.2f  %s", b + 1, bands[b].freq,
                  bands[b].gain, bands[b].q, bands[b].on ? "on" : "off");
         SetAudioReadout("eq", buf);
      }
      // No trailing Dummy: the InvisibleButton above already reserved this
      // (w, h) layout space.
   }

   void DrawEqBody(GraphNode& gn, AudioEffectNode* n)
   {
      EqBandValues bands[5];
      ReadEqBands(n, bands);

      int active = 0;
      float peakDb = 0.0f;
      for (int b = 0; b < 5; b++)
         if (bands[b].on)
            active++;
      {
         // Coarse scan for the idle-stat peak, independent of the
         // visualizer's own (denser, cached) curve.
         const double sampleRate = AudioEngine::Instance().SampleRate() > 0.0
                                      ? AudioEngine::Instance().SampleRate()
                                      : 44100.0;
         const int kScanPoints = 48;
         float bestAbs = -1.0f;
         for (int i = 0; i < kScanPoints; i++)
         {
            const float t = (float)i / (float)(kScanPoints - 1);
            const float f = kFilterVizMinHz * powf(kFilterVizMaxHz / kFilterVizMinHz, t);
            float composite = 0.0f;
            for (int b = 0; b < 5; b++)
               composite += EqDsp::BandMagnitudeDb(bands[b].type, bands[b].freq, bands[b].q, bands[b].gain,
                                                    bands[b].on, f, sampleRate);
            if (std::fabs(composite) > bestAbs)
            {
               bestAbs = std::fabs(composite);
               peakDb = composite;
            }
         }
      }

      char stat[80];
      snprintf(stat, sizeof(stat), "5 bands - %d active - %+.1f dB peak", active, peakDb);

      const double sampleRate = AudioEngine::Instance().SampleRate() > 0.0
                                   ? AudioEngine::Instance().SampleRate()
                                   : 44100.0;

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawEqVisualizer(n, sampleRate);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      const int selBand = std::clamp((int)(n->Param("selectedBand") + 0.5f), 0, 4);
      const int selType = bands[selBand].type;

      {
         AudioKnobRow row(4);
         row.Dropdown("type", EqDsp::TypeList(), selType, [n, selBand](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr(kEqTypeParam[selBand]) = (float)i;
         });
         row.Knob("freq", n->ParamPtr(kEqFreqParam[selBand]), 20.0f, 20000.0f, "%.0f Hz", kKnobLarge);
         row.Knob("Q", n->ParamPtr(kEqQParam[selBand]), 0.1f, 18.0f, "%.2f", kKnobLarge);

         const bool gainLive = EqDsp::UsesGain(selType);
         if (!gainLive)
            ImGui::BeginDisabled();
         row.Knob("gain", n->ParamPtr(kEqGainParam[selBand]), -24.0f, 24.0f, "%.1f dB", kKnobLarge);
         if (!gainLive)
            ImGui::EndDisabled();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Dynamics -----------------------------------------------------
   // Transfer curve (input dB -> output dB) with the live operating point
   // riding on it and a gain-reduction bar down the right edge - §1.2's
   // visualizer. The curve is main-thread from params (DynamicsDsp::
   // GainComputerDb, the same pure function the kernel's own per-sample gain
   // computer uses - never the live running kernel, per audio-node-ui-
   // system.md §3f); the dot and bar are the kernel's two published
   // ExtraMeterValue()s.
   const float kDynVizMinDb = -60.0f;
   const float kDynVizMaxDb = 6.0f;

   float DynVizXToDb(float x, float x0, float w)
   {
      const float t = std::clamp((x - x0) / std::max(1.0f, w), 0.0f, 1.0f);
      return kDynVizMinDb + t * (kDynVizMaxDb - kDynVizMinDb);
   }

   float DynVizDbToX(float db, float x0, float w)
   {
      const float t = (db - kDynVizMinDb) / (kDynVizMaxDb - kDynVizMinDb);
      return x0 + std::clamp(t, 0.0f, 1.0f) * w;
   }

   float DynVizDbToY(float db, float y0, float h)
   {
      const float t = (db - kDynVizMinDb) / (kDynVizMaxDb - kDynVizMinDb);
      return y0 + h - std::clamp(t, 0.0f, 1.0f) * h;
   }

   void DrawDynamicsVisualizer(AudioEffectNode* n, float threshold, float ratio, float makeupDb)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const float curveW = w;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      static const float kDbTicks[] = { -48.0f, -36.0f, -24.0f, -12.0f, 0.0f };
      for (float db : kDbTicks)
      {
         const float x = DynVizDbToX(db, origin.x, curveW);
         const float y = DynVizDbToY(db, origin.y, h);
         dl->AddLine(ImVec2(x, origin.y), ImVec2(x, br.y), db == 0.0f ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
         dl->AddLine(ImVec2(origin.x, y), ImVec2(origin.x + curveW, y),
                     db == 0.0f ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
         char tickBuf[8];
         snprintf(tickBuf, sizeof(tickBuf), "%.0f", db);
         dl->AddText(ImVec2(origin.x + 3.0f, y - (db == 0.0f ? 14.0f : 1.0f)), ScopeTextCol(), tickBuf);
      }

      // 1:1 reference diagonal (unprocessed signal), dim.
      dl->AddLine(ImVec2(DynVizDbToX(kDynVizMinDb, origin.x, curveW), DynVizDbToY(kDynVizMinDb, origin.y, h)),
                  ImVec2(DynVizDbToX(kDynVizMaxDb, origin.x, curveW), DynVizDbToY(kDynVizMaxDb, origin.y, h)),
                  IM_COL32(255, 255, 255, 24), 1.0f);

      // The gain-computer curve itself, with makeup gain folded in so the
      // picture matches what actually comes out.
      dl->PathClear();
      const int kNumPoints = 96;
      for (int i = 0; i < kNumPoints; i++)
      {
         const float x = origin.x + (float)i * (curveW / (float)(kNumPoints - 1));
         const float xDb = DynVizXToDb(x, origin.x, curveW);
         const float yDb = DynamicsDsp::GainComputerDb(xDb, threshold, ratio) + makeupDb;
         dl->PathLineTo(ImVec2(x, DynVizDbToY(yDb, origin.y, h)));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "%.0f dB in -> %.0f dB out, %.0f:1", threshold, threshold + makeupDb, ratio);
         SetAudioReadout("dynamics", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawDynamicsBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool analog = n->Param("analog") != 0.0f;
      char stat[96];
      snprintf(stat, sizeof(stat), "compress %.0f:1 @ %.0f dB%s", n->Param("ratio"), n->Param("threshold"),
               analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawDynamicsVisualizer(n, n->Param("threshold"), n->Param("ratio"), n->Param("makeup"));
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      // KHS Audio Compressor's control surface: threshold, ratio, attack,
      // release, makeup, mix - two rows of three so every knob (mix
      // included) reads as one of the same row instead of mix living apart
      // in its own slider section.
      {
         AudioKnobRow row(3, kKnobLarge);
         row.Knob("threshold", n->ParamPtr("threshold"), -60.0f, 0.0f, "%.1f dB", kKnobLarge);
         row.Knob("ratio", n->ParamPtr("ratio"), 1.0f, 20.0f, "%.1f:1", kKnobLarge);
         row.Knob("attack", n->ParamPtr("attack"), 0.05f, 200.0f, "%.2f ms", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(3, kKnobLarge);
         row.Knob("release", n->ParamPtr("release"), 5.0f, 2000.0f, "%.0f ms", kKnobLarge);
         row.Knob("makeup", n->ParamPtr("makeup"), -12.0f, 24.0f, "%.1f dB", kKnobLarge);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(3, 20.0f, 0.0f, false);
         bool rms = n->Param("detectorRms") != 0.0f;
         if (row.Checkbox("RMS##dynRms", &rms))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("detectorRms") = rms ? 1.0f : 0.0f;
         }
         bool external = n->Param("sidechainExternal") != 0.0f;
         if (row.Checkbox("sidechain##dynSidechain", &external))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("sidechainExternal") = external ? 1.0f : 0.0f;
         }
         bool analogBool = analog;
         if (row.Checkbox("analog##dynAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.End();
      }

      EndAudioBody();
   }

   // ---- Limiter ----------------------------------------------------------
   // A vertical gain-reduction meter, 0/-10/-20 dB scale, bar growing
   // downward from the 0 dB line by the live reduction amount - the shape
   // the reference brief asked for, and distinct enough from
   // DrawStripMeter's plain level bar (no scale, grows up) to warrant its
   // own small ImDrawList routine rather than reusing that primitive.
   void DrawLimiterVisualizer(AudioEffectNode* n, float x, float y, float w, float h)
   {
      ImDrawList* dl = ImGui::GetWindowDrawList();
      const ImVec2 origin(x, y);
      const ImVec2 br(x + w, y + h);
      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 3.0f);
      dl->PushClipRect(origin, br, true);

      const float grDb = std::clamp(n->ExtraMeterValue(0), 0.0f, 20.0f);

      static const float kTicks[] = { 0.0f, -10.0f, -20.0f };
      for (float db : kTicks)
      {
         const float t = std::clamp(-db / 20.0f, 0.0f, 1.0f);
         const float ty = y + t * h;
         dl->AddLine(ImVec2(x, ty), ImVec2(br.x, ty), db == 0.0f ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
         char buf[8];
         snprintf(buf, sizeof(buf), "%.0f", db);
         dl->AddText(ImVec2(x + 3.0f, ty - (db == 0.0f ? 12.0f : 1.0f)), ScopeTextCol(), buf);
      }

      const float barBottom = y + std::clamp(grDb / 20.0f, 0.0f, 1.0f) * h;
      if (barBottom > y + 1.0f)
         dl->AddRectFilled(ImVec2(x + 4.0f, y), ImVec2(br.x - 4.0f, barBottom),
                           isLight ? IM_COL32(230, 120, 20, 230) : IM_COL32(255, 160, 60, 220), 2.0f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "-%.1f dB GR, out %.1f dB", grDb, n->ExtraMeterValue(1));
         SetAudioReadout("limiter", buf);
      }
   }

   void DrawLimiterBody(GraphNode& gn, AudioEffectNode* n)
   {
      char stat[64];
      snprintf(stat, sizeof(stat), "%.0f dB thresh, -%.1f dB GR", n->Param("threshold"),
               std::clamp(n->ExtraMeterValue(0), 0.0f, 20.0f));

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      const float meterW = 64.0f;
      const float meterGap = 12.0f;
      const float meterRightPad = 12.0f;
      const float savedContentW = gAudioContentW;
      const float knobAreaW = savedContentW - meterW - meterGap - meterRightPad;
      const float bodyTop = ImGui::GetCursorScreenPos().y;

      // Two rows of two beside a full-height meter, per the reference
      // layout: threshold/release above, in/out gain below.
      gAudioContentW = knobAreaW;
      {
         AudioKnobRow row(2, kKnobLarge);
         row.Knob("threshold", n->ParamPtr("threshold"), -30.0f, 0.0f, "%.1f dB", kKnobLarge);
         row.Knob("release", n->ParamPtr("release"), 5.0f, 1000.0f, "%.0f ms", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(2, kKnobLarge);
         row.Knob("in gain", n->ParamPtr("inGain"), -12.0f, 24.0f, "%.1f dB", kKnobLarge);
         row.Knob("out gain", n->ParamPtr("outGain"), -24.0f, 12.0f, "%.1f dB", kKnobLarge);
         row.End();
      }
      gAudioContentW = savedContentW;

      const float bodyBottom = ImGui::GetCursorScreenPos().y;
      DrawLimiterVisualizer(n, gAudioContentX + knobAreaW + meterGap, bodyTop, meterW, bodyBottom - bodyTop);

      EndAudioBody();
   }

   // ---- Delay ----------------------------------------------------------
   // Decaying tap bars on a time axis, synthesized from feedback (amplitude
   // = feedback^n at n * delay time) - there's only ever one discrete delay
   // path now, so this is exact, not illustrative. Deliberately not a full
   // IR view (README §1's drawing-cost warning): main-thread from params
   // only, except the two meter values for the level pair beneath.
   void DrawDelayVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const float barsH = h - 30.0f;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      // Amplitude gridlines, same 25%-step reading aid Dynamics/Reverb use.
      for (int i = 1; i < 4; i++)
      {
         const float y = origin.y + barsH - (float)i * 0.25f * barsH;
         dl->AddLine(ImVec2(origin.x, y), ImVec2(br.x, y), ScopeGridCol(), 1.0f);
      }

      const bool sync = n->Param("sync") != 0.0f;
      const int rateDiv = std::clamp((int)(n->Param("rateDiv") + 0.5f), 0, MusicTime::kNumRateDivisions - 1);
      float baseSeconds;
      if (sync)
      {
         const double bpm = std::max(1.0f, Transport::Instance().Tempo());
         baseSeconds = (float)(MusicTime::BeatsFor((MusicTime::RateDivision)rateDiv) * 60.0 / bpm);
      }
      else
         baseSeconds = n->Param("timeMs") * 0.001f;

      const float barHalfW = 2.5f;
      const float feedback = std::min(1.0f, n->Param("feedback") / 100.0f); // visualize decay only
      const float windowSeconds = std::max(0.006f, baseSeconds * 6.0f);
      float amp = 1.0f;
      float t = baseSeconds;
      for (int tapIdx = 0; tapIdx < 24 && amp > 0.02f && t < windowSeconds; tapIdx++)
      {
         const float x = origin.x + std::clamp(t / windowSeconds, 0.0f, 1.0f) * w;
         const float barTopY = origin.y + barsH - amp * barsH;
         dl->AddRectFilled(ImVec2(x - barHalfW, barTopY), ImVec2(x + barHalfW, origin.y + barsH),
                           isLight ? IM_COL32(30, 110, 230, 230) : IM_COL32(150, 214, 255, 220));
         amp *= feedback;
         t += baseSeconds;
      }

      dl->AddLine(ImVec2(origin.x, origin.y + barsH), ImVec2(br.x, origin.y + barsH), ScopeMidLineCol(),
                  1.0f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "%.0f ms  fb %.0f%%", baseSeconds * 1000.0f, feedback * 100.0f);
         SetAudioReadout("delay", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawDelayBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool sync = n->Param("sync") != 0.0f;
      const bool bounce = n->Param("bounce") != 0.0f;
      const bool analog = n->Param("analog") != 0.0f;

      char stat[112];
      if (sync)
         snprintf(stat, sizeof(stat), "%s - %.0f%% fb - %.0f%% wet%s",
                  MusicTime::RateDivisionName((int)(n->Param("rateDiv") + 0.5f)), n->Param("feedback"),
                  n->mix * 100.0f, analog ? " - analog" : "");
      else
         snprintf(stat, sizeof(stat), "%.0f ms - %.0f%% fb - %.0f%% wet%s", n->Param("timeMs"), n->Param("feedback"),
                  n->mix * 100.0f, analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawDelayVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      // KHS Audio Delay's control surface: Time, Tone, Feedback, Pan, Duck,
      // Mix - two rows of three (Bounce is the checkbox below, matching the
      // reference's inline on/off switch). A single row of 6 spread the
      // knobs across the full 440px body with wide, sparse gaps and left the
      // node much wider than it was tall; matching Dynamics' two-row grammar
      // fixes both at once. Rate is a dropdown when synced, a knob when
      // free.
      {
         AudioKnobRow row(3);
         if (sync)
         {
            row.Dropdown("rate", MusicTime::RateDivisionList(), (int)(n->Param("rateDiv") + 0.5f), [n](int i) {
               PushUndoCheckpoint();
               *n->ParamPtr("rateDiv") = (float)i;
            });
         }
         else
         {
            row.Knob("time", n->ParamPtr("timeMs"), 1.0f, 2000.0f, "%.0f ms", kKnobLarge);
         }
         row.Knob("tone", n->ParamPtr("tone"), -1.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("feedback", n->ParamPtr("feedback"), 0.0f, 110.0f, "%.0f%%", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(3);
         row.Knob("pan", n->ParamPtr("pan"), -1.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("duck", n->ParamPtr("ducking"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      {
         // Tight checkbox-only row (maxDia 20 = checkbox frame height,
         // hasCaptions=false) with a small 8px headerRowH gap so it doesn't
         // read as too compacted against the knob row above - same pattern
         // as Pitch Shift/Ring Mod/Flanger/Phaser/Bitcrush/etc.'s trailing
         // analog rows.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         bool syncBool = sync;
         if (row.Checkbox("sync to tempo##delaySync", &syncBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("sync") = syncBool ? 1.0f : 0.0f;
         }
         bool bounceBool = bounce;
         if (row.Checkbox("bounce##delayBounce", &bounceBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("bounce") = bounceBool ? 1.0f : 0.0f;
         }
         bool analogBool = analog;
         if (row.Checkbox("analog##delayAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.End();
      }

      EndAudioBody();
   }

   // ---- Reverb -----------------------------------------------------------
   // RT60 decay envelope on a time axis, with the predelay gap drawn before
   // the tail begins - a straight line from full amplitude at t=predelay
   // down to -60dB at t=predelay+decay, main-thread from params only (the
   // FDN's actual impulse response is not something worth computing here -
   // README §1's drawing-cost warning - the envelope shape is what a user
   // tweaking size/decay/damping actually needs to see).
   void DrawReverbVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float predelaySeconds = n->Param("predelay") * 0.001f;
      const float decaySeconds = std::max(0.05f, n->Param("decay"));
      const float dampFrac = std::clamp(n->Param("damping"), 0.0f, 1.0f);
      const float windowSeconds = 5.0f;

      for (int sec = 1; sec < (int)windowSeconds; sec++)
      {
         const float x = origin.x + ((float)sec / windowSeconds) * w;
         dl->AddLine(ImVec2(x, origin.y), ImVec2(x, br.y), ScopeGridCol(), 1.0f);
      }
      for (int i = 1; i < 4; i++)
      {
         const float y = br.y - (float)i * 0.25f * (h - 6.0f);
         dl->AddLine(ImVec2(origin.x, y), ImVec2(br.x, y), ScopeGridCol(), 1.0f);
      }

      const float predelayX = origin.x + std::clamp(predelaySeconds / windowSeconds, 0.0f, 1.0f) * w;
      dl->AddLine(ImVec2(predelayX, origin.y), ImVec2(predelayX, br.y), ScopeMidLineCol(), 1.0f);

      dl->PathClear();
      const int kNumPoints = 64;
      for (int i = 0; i < kNumPoints; i++)
      {
         const float t = (float)i / (float)(kNumPoints - 1) * windowSeconds;
         float amp;
         if (t < predelaySeconds)
            amp = 1.0f;
         else
         {
            const float tailT = t - predelaySeconds;
            const float rt60Frac = std::clamp(tailT / decaySeconds, 0.0f, 4.0f);
            const float shapedFrac = rt60Frac * (1.0f + dampFrac * 0.5f);
            amp = std::pow(10.0f, -3.0f * shapedFrac);
         }
         const float x = origin.x + (t / windowSeconds) * w;
         const float y = br.y - amp * (h - 6.0f);
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "%.1f s RT60", decaySeconds);
         SetAudioReadout("reverb", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawReverbBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool analog = n->Param("analog") != 0.0f;
      char stat[96];
      snprintf(stat, sizeof(stat), "%.1f s - %.0f%% wet%s", n->Param("decay"), n->mix * 100.0f,
               analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawReverbVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      // Tier 1: size, decay, damping, predelay, width, mix - one mode
      // (algorithmic FDN, no engine dropdown). Two rows of 3, matching
      // Dynamics and Delay's grammar. Mix is always the last cell of the
      // last row across every AudioEffects node - the standard bottom-right
      // spot, so it reads the same in every effect regardless of how many
      // params sit ahead of it.
      {
         AudioKnobRow row(3);
         row.Knob("size", n->ParamPtr("size"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("decay", n->ParamPtr("decay"), 0.1f, 20.0f, "%.2f s", kKnobLarge);
         row.Knob("damping", n->ParamPtr("damping"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(3);
         row.Knob("predelay", n->ParamPtr("predelay"), 0.0f, 500.0f, "%.0f ms", kKnobLarge);
         row.Knob("width", n->ParamPtr("width"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      {
         // Tight checkbox-only row (maxDia 20 = checkbox frame height,
         // hasCaptions=false) with a small 8px headerRowH gap so it doesn't
         // read as too compacted against the knob row above - same pattern
         // as Pitch Shift/Ring Mod/Flanger/Phaser/Bitcrush/etc.'s trailing
         // analog rows.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         bool analogBool = analog;
         if (row.Checkbox("analog##reverbAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Drive ------------------------------------------------------------
   // The transfer curve itself, input -1..+1 -> output -1..+1 - the node's
   // identity, and (per §1.5's spec) main-thread from drive/bias alone, not
   // the live running kernel - same discipline as Dynamics' curve. Tone is
   // a post-shape filter, not part of the static curve, so it's left out
   // here exactly as Delay's tone tilt is left out of the tap-bar view.
   void DrawDriveVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      // Center gridlines (x=0, y=0) plus quarter-amplitude ticks, the same
      // reading aid Dynamics/Reverb give their curves.
      for (int i = -2; i <= 2; i++)
      {
         const float x = origin.x + (0.5f + 0.25f * (float)i) * w;
         const float y = origin.y + (0.5f - 0.25f * (float)i) * h;
         const bool center = (i == 0);
         dl->AddLine(ImVec2(x, origin.y), ImVec2(x, br.y), center ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
         dl->AddLine(ImVec2(origin.x, y), ImVec2(br.x, y), center ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
      }

      // 1:1 reference diagonal (unshaped signal), dim.
      dl->AddLine(ImVec2(origin.x, br.y), ImVec2(br.x, origin.y), ScopeMidLineCol(), 1.0f);

      const float driveDb = n->Param("drive");
      const float bias = n->Param("bias");
      const float color = n->Param("color");

      dl->PathClear();
      const int kNumPoints = 96;
      for (int i = 0; i < kNumPoints; i++)
      {
         const float xIn = -1.0f + 2.0f * (float)i / (float)(kNumPoints - 1);
         const float yOut = std::clamp(DriveDsp::Shape(xIn, driveDb, bias, color), -1.0f, 1.0f);
         const float x = origin.x + (0.5f + 0.5f * xIn) * w;
         const float y = origin.y + (0.5f - 0.5f * yOut) * h;
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "%.1f dB drive, bias %.2f", driveDb, bias);
         SetAudioReadout("drive", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawDriveBody(GraphNode& gn, AudioEffectNode* n)
   {
      char stat[80];
      snprintf(stat, sizeof(stat), "%.1f dB drive - %.0f%% wet", n->Param("drive"), n->mix * 100.0f);

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawDriveVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      // Tier 1 only: drive, bias, tone, color, output, mix - one processing
      // mode (tanh blended toward arctan via `color`), no curve dropdown.
      // Two rows of three so mix lands in its standard bottom-right spot,
      // matching Dynamics/Delay/Reverb's grammar.
      {
         AudioKnobRow row(3);
         row.Knob("drive", n->ParamPtr("drive"), 0.0f, 40.0f, "%.1f dB", kKnobLarge);
         row.Knob("bias", n->ParamPtr("bias"), -1.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("tone", n->ParamPtr("tone"), -1.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(3);
         row.Knob("color", n->ParamPtr("color"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("output", n->ParamPtr("output"), -24.0f, 12.0f, "%.1f dB", kKnobLarge);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      EndAudioBody();
   }

   // ---- Wavetable Shaper ---------------------------------------------------
   // The transfer curve itself, input -1..+1 -> output -1..+1, exactly like
   // Drive's - main-thread from params alone via WavetableShaperDsp::Shape,
   // never the live kernel, so it's always meaningful with no audio running.
   // The one addition Drive's curve doesn't have: a live operating-point dot
   // at the kernel's last input sample (ExtraMeterValue(0)), since this curve
   // is otherwise entirely static and the dot is what makes it read as an
   // instrument rather than a diagram.
   void DrawWavetableShaperVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      for (int i = -2; i <= 2; i++)
      {
         const float x = origin.x + (0.5f + 0.25f * (float)i) * w;
         const float y = origin.y + (0.5f - 0.25f * (float)i) * h;
         const bool center = (i == 0);
         dl->AddLine(ImVec2(x, origin.y), ImVec2(x, br.y), center ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
         dl->AddLine(ImVec2(origin.x, y), ImVec2(br.x, y), center ? ScopeMidLineCol() : ScopeGridCol(), 1.0f);
      }

      // 1:1 reference diagonal (unshaped signal), dim.
      dl->AddLine(ImVec2(origin.x, br.y), ImVec2(br.x, origin.y), ScopeMidLineCol(), 1.0f);

      const int table = (int)(n->Param("table") + 0.5f);
      const float position = n->Param("position");
      const float driveDb = n->Param("drive");
      const float bias = n->Param("bias");
      const float smooth = n->Param("smooth");
      const float stereo = std::clamp(n->Param("stereo"), 0.0f, 1.0f);
      const float positionL = position - stereo * 0.5f;
      const float positionR = position + stereo * 0.5f;

      // At stereo=0 positionL==positionR==position, so the two traces below
      // draw on top of each other and it looks exactly like the single-curve
      // original - same alpha-layering technique as DrawChorusVisualizer's
      // taps, not a second visualizer mode.
      const int kNumPoints = 96;
      for (int pass = 0; pass < (stereo > 0.0f ? 2 : 1); pass++)
      {
         const float tracePosition = (pass == 1) ? positionR : positionL;
         const int alpha = (stereo > 0.0f) ? (pass == 0 ? 200 : 150) : 255;
         dl->PathClear();
         for (int i = 0; i < kNumPoints; i++)
         {
            const float xIn = -1.0f + 2.0f * (float)i / (float)(kNumPoints - 1);
            const float yOut =
               std::clamp(WavetableShaperDsp::Shape(xIn, table, tracePosition, driveDb, bias, smooth), -1.0f, 1.0f);
            const float x = origin.x + (0.5f + 0.5f * xIn) * w;
            const float y = origin.y + (0.5f - 0.5f * yOut) * h;
            dl->PathLineTo(ImVec2(x, y));
         }
         dl->PathStroke(isLight ? IM_COL32(30, 110, 230, alpha) : IM_COL32(150, 214, 255, alpha), 0, 1.8f);
      }

      // Live operating-point dot at the kernel's last input sample.
      const float lastIn = std::clamp(n->ExtraMeterValue(0), -1.0f, 1.0f);
      const float lastOut =
         std::clamp(WavetableShaperDsp::Shape(lastIn, table, position, driveDb, bias, smooth), -1.0f, 1.0f);
      const ImVec2 dot(origin.x + (0.5f + 0.5f * lastIn) * w, origin.y + (0.5f - 0.5f * lastOut) * h);
      dl->AddCircleFilled(dot, 3.5f, isLight ? IM_COL32(230, 120, 20, 230) : IM_COL32(255, 214, 120, 230));

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[80];
         snprintf(buf, sizeof(buf), "%s, position %.2f, %.1f dB drive", Wavetable::TableName(table), position,
                   driveDb);
         SetAudioReadout("wavetable shaper", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawWavetableShaperBody(GraphNode& gn, AudioEffectNode* n)
   {
      const float stereo = n->Param("stereo");
      char stat[112];
      if (stereo > 0.0f)
         snprintf(stat, sizeof(stat), "%s - %.1f dB drive - %.0f%% stereo - %.0f%% wet",
                  Wavetable::TableName((int)(n->Param("table") + 0.5f)), n->Param("drive"), stereo * 100.0f,
                  n->mix * 100.0f);
      else
         snprintf(stat, sizeof(stat), "%s - %.1f dB drive - %.0f%% wet",
                  Wavetable::TableName((int)(n->Param("table") + 0.5f)), n->Param("drive"), n->mix * 100.0f);

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawWavetableShaperVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      // Tier 1 only: table, position, drive, stereo, bias, smooth, output,
      // mix - one processing mode. `table` is the curve's identity (a
      // dropdown, same carve-out as Audio Filter's `type`/Ring Mod's
      // `waveform`), not a second mode selector. Both rows are 4 cells so
      // they share column edges (P1); row 1 is table/position/drive/stereo,
      // row 2 is bias/smooth/output/mix so mix still lands in the standard
      // bottom-right spot every AudioEffects node's grammar puts it in.
      {
         AudioKnobRow row(4);
         const int table = (int)(n->Param("table") + 0.5f);
         row.Dropdown("table", WavetableNames(), table, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("table") = (float)i;
         }, WavetableCategories());
         row.Knob("position", n->ParamPtr("position"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("drive", n->ParamPtr("drive"), 0.0f, 24.0f, "%.1f dB", kKnobLarge);
         row.Knob("stereo", n->ParamPtr("stereo"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }
      {
         AudioKnobRow row(4);
         row.Knob("bias", n->ParamPtr("bias"), -1.0f, 1.0f, "%.2f", kKnobSmall);
         row.Knob("smooth", n->ParamPtr("smooth"), 0.0f, 1.0f, "%.2f", kKnobSmall);
         row.Knob("output", n->ParamPtr("output"), -24.0f, 12.0f, "%.1f dB", kKnobSmall);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobSmall);
         row.End();
      }

      EndAudioBody();
   }

   // ---- Stereo -------------------------------------------------------------
   // A polar stereo-field imager matching the classic hardware-plugin
   // goniometer layout: concentric dB-ring arcs fanning up from a bottom-
   // center apex, a dB scale along the baseline (loud at the outer edges,
   // quiet toward center), and a filled wedge whose two edges swing left/
   // right of vertical - `width` opens the wedge, `pan` shifts it - the
   // same picture the reference plugin's stereo field display uses.
   // `bassMono` is a frequency-domain effect a polar field can't depict, so
   // it's shown as a text label instead.
   void DrawStereoVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();
      const ImVec2 apex(origin.x + w * 0.5f, br.y - 20.0f);
      const float radius = std::min(w * 0.48f, h - 26.0f);

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      // Concentric dB rings, apex-centered, sweeping only the upper half.
      const int kNumRings = 5;
      for (int i = 1; i <= kNumRings; i++)
      {
         const float r = radius * (float)i / (float)kNumRings;
         dl->PathClear();
         dl->PathArcTo(apex, r, (float)M_PI, 2.0f * (float)M_PI, 32);
         dl->PathStroke(ScopeGridCol(), 0, 1.0f);
      }
      dl->AddLine(ImVec2(apex.x, apex.y), ImVec2(apex.x, apex.y - radius), ScopeMidLineCol(), 1.0f);
      dl->AddLine(ImVec2(apex.x - radius, apex.y), ImVec2(apex.x + radius, apex.y), ScopeMidLineCol(), 1.0f);

      static const char* kDbLabels[] = { "0", "-6", "-12", "-18", "-24" };
      for (int i = 0; i < kNumRings; i++)
      {
         const float t = (float)i / (float)kNumRings;
         const float x = apex.x - radius + t * radius;
         dl->AddText(ImVec2(x - 6.0f, apex.y + 4.0f), ScopeTextCol(), kDbLabels[kNumRings - 1 - i]);
         const float xr = apex.x + radius - t * radius;
         dl->AddText(ImVec2(xr - 6.0f, apex.y + 4.0f), ScopeTextCol(), kDbLabels[kNumRings - 1 - i]);
      }

      const float width = std::clamp(n->Param("width"), 0.0f, 2.0f);
      const float pan = std::clamp(n->Param("pan"), -1.0f, 1.0f);
      const float bassMonoHz = std::max(0.0f, n->Param("bassMono"));

      const float widthNorm = width * 0.5f;
      const float maxHalfAngle = 75.0f * (float)M_PI / 180.0f;
      const float panShift = pan * 30.0f * (float)M_PI / 180.0f;
      const float leftAngle = panShift - maxHalfAngle * widthNorm;
      const float rightAngle = panShift + maxHalfAngle * widthNorm;
      const float wedgeR = radius * 0.92f;

      auto polar = [&](float angle) {
         return ImVec2(apex.x + wedgeR * sinf(angle), apex.y - wedgeR * cosf(angle));
      };
      const ImVec2 leftPt = polar(leftAngle);
      const ImVec2 rightPt = polar(rightAngle);

      dl->PathClear();
      dl->PathLineTo(apex);
      dl->PathLineTo(leftPt);
      dl->PathLineTo(rightPt);
      dl->PathFillConvex(isLight ? IM_COL32(110, 90, 210, 80) : IM_COL32(150, 130, 230, 90));

      dl->PathClear();
      dl->PathLineTo(leftPt);
      dl->PathLineTo(apex);
      dl->PathLineTo(rightPt);
      dl->PathStroke(isLight ? IM_COL32(120, 80, 230, 235) : IM_COL32(190, 170, 255, 235), 0, 1.8f);

      if (bassMonoHz > 0.0f)
      {
         char blo[24];
         snprintf(blo, sizeof(blo), "mono <%.0f Hz", bassMonoHz);
         dl->AddText(ImVec2(origin.x + 6.0f, origin.y + 6.0f),
                     isLight ? IM_COL32(210, 100, 20, 230) : IM_COL32(255, 196, 120, 210), blo);
      }

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[48];
         const float corr = std::clamp(n->ExtraMeterValue(0), -1.0f, 1.0f);
         snprintf(buf, sizeof(buf), "width %.2f - pan %+.2f - corr %.2f", width, pan, corr);
         SetAudioReadout("stereo", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawStereoBody(GraphNode& gn, AudioEffectNode* n)
   {
      char stat[80];
      snprintf(stat, sizeof(stat), "width %.2f - pan %.2f", n->Param("width"), n->Param("pan"));

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawStereoVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      AudioKnobRow row(3);
      row.Knob("width", n->ParamPtr("width"), 0.0f, 2.0f, "%.2f", kKnobLarge);
      row.Knob("pan", n->ParamPtr("pan"), -1.0f, 1.0f, "%.2f", kKnobLarge);
      row.Knob("bass mono", n->ParamPtr("bassMono"), 0.0f, 500.0f, "%.0f Hz", kKnobLarge, false, false, AudioWidgetStyle::KnobSkewBassMono);
      row.End();

      EndAudioBody();
   }

   // ---- Pitch Shifter --------------------------------------------------
   // A simple bipolar meter (-24..+24 semitones) rather than a spectrogram -
   // the shift amount is the node's whole identity and a spectrogram would
   // cost far more to draw than this effect's DSP itself (README §1).
   void DrawPitchShiftVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float midY = origin.y + h * 0.5f;
      dl->AddLine(ImVec2(origin.x, midY), ImVec2(br.x, midY), ScopeGridCol(), 1.0f);
      const float centerX = origin.x + 0.5f * w;
      dl->AddLine(ImVec2(centerX, origin.y), ImVec2(centerX, br.y), ScopeMidLineCol(), 1.0f);

      const float pitch = std::clamp(n->Param("pitch"), -24.0f, 24.0f);
      const float t = 0.5f + 0.5f * (pitch / 24.0f);
      const float markX = origin.x + t * w;
      dl->AddCircleFilled(ImVec2(markX, midY), 6.0f, isLight ? IM_COL32(30, 110, 230, 245) : IM_COL32(150, 214, 255, 245));

      char buf[32];
      snprintf(buf, sizeof(buf), "%+.1f st", pitch);
      dl->AddText(ImVec2(origin.x + 6.0f, origin.y + 6.0f), ScopeTextCol(), buf);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
         SetAudioReadout("pitch shifter", buf);

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawPitchShiftBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool analog = n->Param("analog") != 0.0f;
      char stat[96];
      snprintf(stat, sizeof(stat), "%+.1f st - %.0f ms grain%s", n->Param("pitch"), n->Param("grain"),
               analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawPitchShiftVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      AudioKnobRow row(3);
      row.Knob("pitch", n->ParamPtr("pitch"), -24.0f, 24.0f, "%+.1f st", kKnobLarge);
      row.Knob("grain", n->ParamPtr("grain"), 10.0f, 250.0f, "%.0f ms", kKnobLarge);
      row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
      row.End();

      {
         // maxDia 20 (checkbox frame height) + hasCaptions=false: a
         // checkbox-only row draws its label inline, never below the control
         // the way a knob's caption does, so leaving this at the default
         // AudioKnobRow(3) (maxDia kKnobSmall=40, hasCaptions=true) reserved a
         // full knob-height-plus-caption-strip that nothing ever drew into -
         // the dead gap between this checkbox and the node's bottom border.
         // Same tight-row pattern already used by Dynamics/SpecBlur/Switcher's
         // trailing checkbox rows.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         bool analogBool = analog;
         if (row.Checkbox("analog##pitchShiftAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // Shared rate control for Tremolo/Chorus/Flanger/Phaser - a rateDiv
   // dropdown when synced, a free-Hz knob when not - added as the next cell
   // of an already-open AudioKnobRow so it sits alongside the effect's other
   // knobs instead of claiming a row of its own. `rateLo`/`rateHi` match
   // each effect's own EffectDefs "rate" range (Tremolo's is 0.05-20 Hz;
   // Chorus/Flanger/Phaser share 0.02-5 Hz, the default here).
   void AddSyncedRateCell(AudioKnobRow& row, AudioEffectNode* n, float rateLo = 0.02f, float rateHi = 5.0f)
   {
      const bool sync = n->Param("sync") != 0.0f;
      if (sync)
      {
         row.Dropdown("rate", MusicTime::RateDivisionList(), (int)(n->Param("rateDiv") + 0.5f), [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("rateDiv") = (float)i;
         });
         // The free-Hz knob isn't drawn while synced, but it still must
         // consume a gParamCounter ordinal - same trick, same reason, as
         // DrawRateModeControls' reserved-slot comment above: ordinals are
         // assigned by draw order, and the dropdown just drawn is a
         // *discrete* param (numbered from a hash of its label, see
         // DiscreteParamSlot) that doesn't touch gParamCounter at all. Skipping
         // the knob call here would leave this cell consuming zero ordinals
         // while synced versus one while free, shifting every later
         // gParamCounter-numbered control in the body (this effect's own
         // "mix") down by one the instant sync flips, silently repointing
         // whatever cable was patched into it.
         ParamRef rateSlot;
         rateSlot.nodeIndex = gCurrentNodeIndex;
         rateSlot.paramIndex = gParamCounter++;
         rateSlot.value = n->ParamPtr("rate");
         rateSlot.minValue = rateLo;
         rateSlot.maxValue = rateHi;
         rateSlot.name = "rate";
         Modulation::Instance().RegisterParam(rateSlot);
      }
      else
      {
         row.Knob("rate", n->ParamPtr("rate"), rateLo, rateHi, "%.2f Hz", kKnobLarge);
      }
   }

   // Shared [rate-mode v][rate] pair for the four AudioEffects with a
   // tempo-sync toggle (Tremolo, Chorus, Flanger, Phaser) - the effect-side
   // equivalent of the note generators' DrawRateModeControls. Cell 1 is a
   // Synced/Free dropdown replacing the old free-floating/row "sync to
   // tempo" checkbox (see node-ui-pillars P1/P3); cell 2 is
   // AddSyncedRateCell's existing rate-division-dropdown-or-Hz-knob cell.
   //
   // `syncLabel` must be the exact label id the node's old sync checkbox
   // used (e.g. "sync to tempo##chorusSync"). Discrete params are numbered
   // from a hash of their label, not from draw order (DiscreteParamSlot), so
   // reusing the old label keeps this dropdown on the same pin address the
   // checkbox occupied - an already-saved patch's modulation binding on the
   // sync toggle, if any, still resolves to this control rather than going
   // permanently inactive. Note this does flip that binding's polarity: a
   // cable driving the old checkbox toward 1.0 meant "synced"; driving this
   // 2-option dropdown ("Synced" first, matching the note-generator
   // convention this mirrors) toward 1.0 now selects "Free" instead. That
   // narrow case - a cable bound specifically to the sync toggle itself - is
   // an accepted, documented consequence of the checkbox-to-dropdown
   // conversion; `depth`/`rate`/`mix` bindings are unaffected.
   void AddRateModeCells(AudioKnobRow& row, AudioEffectNode* n, const char* syncLabel,
                         float rateLo, float rateHi)
   {
      static const std::vector<std::string> kSyncModes = { "Synced", "Free" };
      const bool sync = n->Param("sync") != 0.0f;
      row.Dropdown(syncLabel, kSyncModes, sync ? 0 : 1, [n](int i) {
         PushUndoCheckpoint();
         *n->ParamPtr("sync") = (i == 0) ? 1.0f : 0.0f;
      });
      AddSyncedRateCell(row, n, rateLo, rateHi);
   }

   // ---- Chorus -------------------------------------------------------------
   // `taps` sine traces (one per voice), phase-offset by `spread` and
   // amplitude-scaled by `depth` - the same "layered waves" picture the
   // BLEASS/Ableton chorus references use, minus the color-per-voice (this
   // codebase's accent color is used throughout, differentiated by alpha
   // instead). `delay`/`feedback` show in the corner label/opacity; `rate`
   // and `mix` are deliberately not reflected here (an animated live LFO
   // costs more to draw than the effect it illustrates - README §1 - and
   // mix never changes a wet effect's own shape).
   void DrawChorusVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float midY = origin.y + h * 0.5f;
      dl->AddLine(ImVec2(origin.x, midY), ImVec2(br.x, midY), ScopeMidLineCol(), 1.0f);

      const int taps = n->Param("taps") >= 2.5f ? 3 : 2;
      const float spread = std::clamp(n->Param("spread"), 0.0f, 1.0f);
      const float depthMs = n->Param("depth");
      const float delayMs = n->Param("delay");
      const float feedback = std::clamp(n->Param("feedback"), 0.0f, 0.9f);
      const float amp = std::clamp(depthMs / 15.0f, 0.08f, 1.0f) * (h * 0.5f - 8.0f);

      for (int k = 0; k < taps; k++)
      {
         const float voiceOffset = (float)k / (float)taps;
         const float phaseOffset = voiceOffset + spread * 0.5f * ((float)k / (float)std::max(1, taps - 1));
         const int alpha = std::clamp(150 - k * 40 + (int)(feedback * 90.0f), 60, 255);
         dl->PathClear();
         const int kNumPoints = 96;
         for (int i = 0; i < kNumPoints; i++)
         {
            const float t = (float)i / (float)(kNumPoints - 1);
            const float x = origin.x + t * w;
            const float y = midY - amp * sinf(2.0f * (float)M_PI * (t * 2.0f + phaseOffset));
            dl->PathLineTo(ImVec2(x, y));
         }
         dl->PathStroke(isLight ? IM_COL32(30, 110, 230, alpha) : IM_COL32(150, 214, 255, alpha), 0, 1.5f + feedback * 1.5f);
      }

      char buf[24];
      snprintf(buf, sizeof(buf), "%.1f ms", delayMs);
      dl->AddText(ImVec2(origin.x + 6.0f, origin.y + 6.0f), ScopeTextCol(), buf);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char hover[80];
         snprintf(hover, sizeof(hover), "%.1f ms +/- %.1f ms, %d taps, %.0f%% fb", delayMs, depthMs, taps,
                  feedback * 100.0f);
         SetAudioReadout("chorus", hover);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawChorusBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool sync = n->Param("sync") != 0.0f;
      const bool analog = n->Param("analog") != 0.0f;
      char stat[112];
      if (sync)
         snprintf(stat, sizeof(stat), "%.0f taps - %s - %.0f%% wet%s", n->Param("taps"),
                  MusicTime::RateDivisionName((int)(n->Param("rateDiv") + 0.5f)), n->mix * 100.0f,
                  analog ? " - analog" : "");
      else
         snprintf(stat, sizeof(stat), "%.0f taps - %.2f Hz - %.0f%% wet%s", n->Param("taps"), n->Param("rate"),
                  n->mix * 100.0f, analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawChorusVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(3);
         row.Knob("delay", n->ParamPtr("delay"), 1.0f, 30.0f, "%.1f ms", kKnobLarge);
         row.Knob("spread", n->ParamPtr("spread"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("depth", n->ParamPtr("depth"), 0.0f, 15.0f, "%.1f ms", kKnobLarge);
         row.End();
      }
      {
         // 3 cells: rate | feedback | mix - mix stays bottom-right of the
         // last knob row (P4). `row.index` is set explicitly before each
         // call so the *visual* cell a control lands in can differ from
         // its *draw order* - feedback and mix are still called first and
         // second, exactly as before (see the old 4-cell row this
         // replaces), so their gParamCounter ordinals (and any existing
         // patch's modulation bindings on them) don't move; only where
         // they're drawn, and where the sync dropdown moved to (its own
         // row below), changes. AddSyncedRateCell is called last, exactly
         // as it was before (via AddRateModeCells), so rate's ordinal is
         // unaffected too.
         AudioKnobRow row(3);
         row.index = 1;
         row.Knob("feedback", n->ParamPtr("feedback"), 0.0f, 0.9f, "%.2f", kKnobLarge);
         row.index = 2;
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 0;
         AddSyncedRateCell(row, n);
         row.End();
      }

      {
         // 3 cells, all used: sync dropdown left (P3), then the two
         // checkboxes - a clean 3-3-3 grid (P6). The dropdown keeps the
         // exact label id ("sync to tempo##chorusSync") the old
         // AddRateModeCells call used here, matching the discrete-param
         // hash-based addressing AddRateModeCells' own comment documents -
         // any existing patch's modulation binding on the sync control
         // still resolves to this control even though it moved rows.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         static const std::vector<std::string> kSyncModes = { "Synced", "Free" };
         row.Dropdown("sync to tempo##chorusSync", kSyncModes, sync ? 0 : 1, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("sync") = (i == 0) ? 1.0f : 0.0f;
         });
         bool taps3 = n->Param("taps") >= 2.5f;
         if (row.Checkbox("3 taps##chorusTaps", &taps3))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("taps") = taps3 ? 3.0f : 2.0f;
         }
         bool analogBool = analog;
         if (row.Checkbox("analog##chorusAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.End();
      }

      EndAudioBody();
   }

   // ---- Flanger --------------------------------------------------------
   // A dry reference line plus a modulated wet trace whose thickness and
   // ripple sharpness scale with `feedback` - a flanger's resonant comb
   // narrowing as feedback climbs is exactly the "jet swoosh" character the
   // knob controls, so this is the one picture that reads that back
   // directly (the Ableton flanger reference's own dual-wave look, adapted
   // to this codebase's single accent color via a dim dry trace instead of
   // a second hue).
   void DrawFlangerVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float midY = origin.y + h * 0.5f;
      const float delayMs = n->Param("delay");
      const float depthMs = n->Param("depth");
      const float feedback = n->Param("feedback");
      const float amp = std::clamp(depthMs / 10.0f, 0.08f, 1.0f) * (h * 0.5f - 10.0f);
      const float rippleAmp = std::fabs(feedback) * (h * 0.16f);
      const float rippleFreq = 3.0f + std::fabs(feedback) * 5.0f;

      // Dry reference - a flat carrier ripple with no modulation envelope.
      dl->PathClear();
      for (int i = 0; i < 96; i++)
      {
         const float t = (float)i / 95.0f;
         const float x = origin.x + t * w;
         const float y = midY - (h * 0.1f) * sinf(2.0f * (float)M_PI * t * rippleFreq);
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(ScopeMidLineCol(), 0, 1.0f);

      auto drawWet = [&](float phaseOffset, int alpha) {
         dl->PathClear();
         for (int i = 0; i < 96; i++)
         {
            const float t = (float)i / 95.0f;
            const float x = origin.x + t * w;
            const float envelope = amp * sinf(2.0f * (float)M_PI * (t * 2.0f + phaseOffset));
            const float ripple = rippleAmp * sinf(2.0f * (float)M_PI * t * rippleFreq);
            const float y = midY - envelope - ripple;
            dl->PathLineTo(ImVec2(x, y));
         }
         dl->PathStroke(isLight ? IM_COL32(30, 110, 230, alpha) : IM_COL32(150, 214, 255, alpha), 0, 1.4f + std::fabs(feedback) * 2.2f);
      };
      drawWet(0.0f, 235);
      drawWet(n->Param("spread") * 0.5f, 120);

      char buf[24];
      snprintf(buf, sizeof(buf), "%.2f ms", delayMs);
      dl->AddText(ImVec2(origin.x + 6.0f, origin.y + 6.0f), ScopeTextCol(), buf);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char hover[80];
         snprintf(hover, sizeof(hover), "%.2f ms +/- %.2f ms, %+.0f%% fb", delayMs, depthMs, feedback * 100.0f);
         SetAudioReadout("flanger", hover);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawFlangerBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool sync = n->Param("sync") != 0.0f;
      const bool analog = n->Param("analog") != 0.0f;
      char stat[112];
      if (sync)
         snprintf(stat, sizeof(stat), "%s - %.0f%% fb - %.0f%% wet%s",
                  MusicTime::RateDivisionName((int)(n->Param("rateDiv") + 0.5f)), n->Param("feedback") * 100.0f,
                  n->mix * 100.0f, analog ? " - analog" : "");
      else
         snprintf(stat, sizeof(stat), "%.1f ms - %.0f%% fb - %.0f%% wet%s", n->Param("delay"),
                  n->Param("feedback") * 100.0f, n->mix * 100.0f, analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawFlangerVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(3);
         row.Knob("delay", n->ParamPtr("delay"), 0.2f, 15.0f, "%.2f ms", kKnobLarge);
         row.Knob("depth", n->ParamPtr("depth"), 0.0f, 10.0f, "%.2f ms", kKnobLarge);
         row.Knob("feedback", n->ParamPtr("feedback"), -0.95f, 0.95f, "%.2f", kKnobLarge);
         row.End();
      }
      {
         // 3 cells: rate | spread | mix - mix stays bottom-right of the
         // last knob row (P4). row.index is set explicitly before each
         // call so the *visual* cell a control lands in can differ from
         // its *draw order* - see the matching comment in DrawChorusBody.
         // AddSyncedRateCell is called last, exactly as it was before (via
         // AddRateModeCells), so rate's ordinal is unaffected.
         AudioKnobRow row(3);
         row.index = 1;
         row.Knob("spread", n->ParamPtr("spread"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 2;
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 0;
         AddSyncedRateCell(row, n, 0.02f, 5.0f);
         row.End();
      }

      {
         // 3 cells, all used: sync dropdown left (P3), then the analog
         // checkbox, then a skip - matching Chorus/Phaser's row 3 (P6). The
         // dropdown keeps the exact label id ("sync to tempo##flangerSync")
         // the old AddRateModeCells call used here, matching the
         // discrete-param hash-based addressing AddRateModeCells' own
         // comment documents - any existing patch's modulation binding on
         // the sync control still resolves to this control even though it
         // moved rows.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         static const std::vector<std::string> kSyncModes = { "Synced", "Free" };
         row.Dropdown("sync to tempo##flangerSync", kSyncModes, sync ? 0 : 1, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("sync") = (i == 0) ? 1.0f : 0.0f;
         });
         bool analogBool = analog;
         if (row.Checkbox("analog##flangerAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Phaser -----------------------------------------------------------
   // An illustrative magnitude-response curve on a log-frequency axis with
   // `order/2` notches spaced between cutoff*2^-depth and cutoff*2^+depth -
   // the same sweep range PhaserKernel::ProcessBlock itself computes for
   // its allpass coefficients, just static rather than animated (rate is
   // deliberately not reflected - see DrawChorusVisualizer's comment). A
   // second, dimmer trace offset by `spread` shows the right channel's
   // widened sweep.
   void DrawPhaserVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float logMin = log10f(50.0f), logMax = log10f(8000.0f);
      auto freqToX = [&](float hz) {
         const float t = std::clamp((log10f(std::max(hz, 1.0f)) - logMin) / (logMax - logMin), 0.0f, 1.0f);
         return origin.x + t * w;
      };
      for (float hz : { 100.0f, 300.0f, 1000.0f, 3000.0f })
      {
         const float x = freqToX(hz);
         dl->AddLine(ImVec2(x, origin.y), ImVec2(x, br.y), ScopeGridCol(), 1.0f);
      }

      const float cutoff = n->Param("cutoff");
      const float depth = std::clamp(n->Param("depth"), 0.0f, 1.0f);
      const int order = std::clamp((int)(n->Param("order") + 0.5f), 2, PhaserKernel::kMaxStages);
      const int notches = std::max(1, order / 2);
      const float spread = std::clamp(n->Param("spread"), 0.0f, 1.0f);
      const float fcLo = std::max(20.0f, cutoff * powf(2.0f, -depth));
      const float fcHi = cutoff * powf(2.0f, depth);
      const float notchWidthLog = std::max(0.05f, 0.55f / (float)notches);

      auto drawTrace = [&](float freqScale, int alpha) {
         dl->PathClear();
         const int kNumPoints = 128;
         for (int i = 0; i < kNumPoints; i++)
         {
            const float t = (float)i / (float)(kNumPoints - 1);
            const float logHz = logMin + t * (logMax - logMin);
            float mag = 1.0f;
            for (int k = 0; k < notches; k++)
            {
               const float frac = notches > 1 ? (float)k / (float)(notches - 1) : 0.5f;
               const float centerHz = std::clamp(fcLo * powf(fcHi / fcLo, frac) * freqScale, 20.0f, 19000.0f);
               const float logDist = (logHz - log10f(centerHz)) / notchWidthLog;
               mag *= 1.0f - 0.85f * expf(-logDist * logDist * 4.0f);
            }
            const float x = origin.x + t * w;
            const float y = br.y - 6.0f - mag * (h - 16.0f);
            dl->PathLineTo(ImVec2(x, y));
         }
         dl->PathStroke(isLight ? IM_COL32(30, 110, 230, alpha) : IM_COL32(150, 214, 255, alpha), 0, 1.6f);
      };
      drawTrace(1.0f, 235);
      if (spread > 0.01f)
         drawTrace(powf(2.0f, spread * 0.5f), 110);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[80];
         snprintf(buf, sizeof(buf), "%.0f Hz +/- %.1f oct, %d notches", cutoff, depth, notches);
         SetAudioReadout("phaser", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawPhaserBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool sync = n->Param("sync") != 0.0f;
      const bool analog = n->Param("analog") != 0.0f;
      char stat[112];
      if (sync)
         snprintf(stat, sizeof(stat), "%.0f-stage - %s - %.0f%% wet%s", n->Param("order"),
                  MusicTime::RateDivisionName((int)(n->Param("rateDiv") + 0.5f)), n->mix * 100.0f,
                  analog ? " - analog" : "");
      else
         snprintf(stat, sizeof(stat), "%.0f-stage - %.0f Hz - %.0f%% wet%s", n->Param("order"), n->Param("cutoff"),
                  n->mix * 100.0f, analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawPhaserVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(3);
         row.Knob("cutoff", n->ParamPtr("cutoff"), 100.0f, 4000.0f, "%.0f Hz", kKnobLarge);
         row.Knob("depth", n->ParamPtr("depth"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("order", n->ParamPtr("order"), 2.0f, (float)PhaserKernel::kMaxStages, "%.0f", kKnobLarge);
         row.End();
      }
      {
         // 3 cells: rate | spread | mix - mix stays bottom-right of the
         // last knob row (P4). `row.index` is set explicitly before each
         // call so the *visual* cell a control lands in can differ from
         // its *draw order* - spread and mix are still called first and
         // second, exactly as before (see the old 4-cell row this
         // replaces), so their gParamCounter ordinals (and any existing
         // patch's modulation bindings on them) don't move; only where
         // they're drawn, and where the sync dropdown moved to (its own
         // row below), changes. AddSyncedRateCell is called last, exactly
         // as it was before (via AddRateModeCells), so rate's ordinal is
         // unaffected too - see the matching comment in DrawChorusBody.
         AudioKnobRow row(3);
         row.index = 1;
         row.Knob("spread", n->ParamPtr("spread"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 2;
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.index = 0;
         AddSyncedRateCell(row, n);
         row.End();
      }

      {
         // 3 cells: sync dropdown left (P3), then the analog checkbox - a
         // clean 3-3-3 grid matching DrawChorusBody's row 3 (P6). Phaser has
         // no "3 taps" equivalent, so the third cell is a deliberate
         // row.Skip() rather than a fabricated control. The dropdown keeps
         // the exact label id ("sync to tempo##phaserSync") the old
         // AddRateModeCells call used here, matching the discrete-param
         // hash-based addressing AddRateModeCells' own comment documents -
         // any existing patch's modulation binding on the sync control
         // still resolves to this control even though it moved rows.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         static const std::vector<std::string> kSyncModes = { "Synced", "Free" };
         row.Dropdown("sync to tempo##phaserSync", kSyncModes, sync ? 0 : 1, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("sync") = (i == 0) ? 1.0f : 0.0f;
         });
         bool analogBool = analog;
         if (row.Checkbox("analog##phaserAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Bitcrush -----------------------------------------------------------
   // A quantized, sample-and-held sine arch with a solid fill down to the
   // baseline, matching the reference bitcrusher's single-hump filled-
   // staircase look (rather than a centered oscillating line) - `bits`
   // sets the step height (levels on the vertical stairs), `rate` sets the
   // step width (how long each hold lasts).
   void DrawBitcrushVisualizer(AudioEffectNode* n, double sampleRate)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float rateHz = std::max(100.0f, n->Param("rate"));
      const float bits = std::max(1.0f, n->Param("bits"));
      const float levels = powf(2.0f, bits) - 1.0f;
      const float holdSamples = std::max(1.0f, (float)sampleRate / rateHz);
      const float cycleSamples = (float)sampleRate; // one second of illustrative arch at 1 Hz
      const float top = origin.y + 8.0f;
      const float baseY = br.y - 4.0f;

      const int kNumSteps = 160;
      ImVec2 pts[kNumSteps];
      float lastHeld = 0.0f;
      for (int i = 0; i < kNumSteps; i++)
      {
         const float sampleIdx = (float)i / (float)(kNumSteps - 1) * cycleSamples;
         const bool tick = fmodf(sampleIdx, holdSamples) < (cycleSamples / (float)kNumSteps);
         float v = fabsf(sinf((float)M_PI * sampleIdx / cycleSamples));
         if (tick || i == 0)
         {
            v = roundf(v * levels) / levels;
            lastHeld = v;
         }
         else
            v = lastHeld;
         const float x = origin.x + (float)i / (float)(kNumSteps - 1) * w;
         const float y = baseY - v * (baseY - top);
         pts[i] = ImVec2(x, y);
      }

      for (int i = 0; i < kNumSteps - 1; i++)
         dl->AddQuadFilled(pts[i], pts[i + 1], ImVec2(pts[i + 1].x, baseY), ImVec2(pts[i].x, baseY),
                            isLight ? IM_COL32(110, 80, 210, 80) : IM_COL32(150, 110, 230, 110));

      dl->PathClear();
      for (int i = 0; i < kNumSteps; i++)
         dl->PathLineTo(pts[i]);
      dl->PathStroke(isLight ? IM_COL32(120, 80, 230, 245) : IM_COL32(190, 160, 255, 245), 0, 1.8f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      char buf[48];
      snprintf(buf, sizeof(buf), "%.0f Hz - %.0f bit", rateHz, bits);
      if (ImGui::IsMouseHoveringRect(origin, br))
         SetAudioReadout("bitcrush", buf);

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawBitcrushBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool analog = n->Param("analog") != 0.0f;
      char stat[96];
      snprintf(stat, sizeof(stat), "%.0f Hz - %.0f bit - %.0f%% wet%s", n->Param("rate"), n->Param("bits"),
               n->mix * 100.0f, analog ? " - analog" : "");

      const double sampleRate =
         AudioEngine::Instance().SampleRate() > 0.0 ? AudioEngine::Instance().SampleRate() : 44100.0;

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawBitcrushVisualizer(n, sampleRate);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      AudioKnobRow row(3);
      // Labelled "downsample" (not "rate") to match the BLEASS-style
      // reference's own naming - this is the same sample-and-hold rate
      // param as before (BitcrushKernel::kRateHz), a cosmetic relabel only.
      row.Knob("downsample", n->ParamPtr("rate"), 200.0f, 44100.0f, "%.0f Hz", kKnobLarge);
      row.Knob("bits", n->ParamPtr("bits"), 1.0f, 16.0f, "%.0f", kKnobLarge);
      row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
      row.End();

      {
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         bool analogBool = analog;
         if (row.Checkbox("analog##bitcrushAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Transient Shaper -----------------------------------------------
   // A stylized transient spike (fast rise, slow decay) with the attack/
   // sustain knobs shown as gain bars either side, and the kernel's own
   // live transient-amount (ExtraMeterValue(0)) riding on the curve as a
   // dot - the same "picture from params, dot from the kernel" split
   // Dynamics' transfer curve uses.
   // Local dB range for this visualizer only - deliberately not shared with
   // Dynamics' kDynVizMinDb/kDynVizMaxDb (-60..+6), which would clip a
   // +24 dB attack boost off the top of the plot.
   const float kTsVizMinDb = -48.0f;
   const float kTsVizMaxDb = 24.0f;

   float TsVizDbToY(float db, float y0, float h)
   {
      const float t = (db - kTsVizMinDb) / (kTsVizMaxDb - kTsVizMinDb);
      return y0 + h - std::clamp(t, 0.0f, 1.0f) * h;
   }

   void DrawTransientShaperVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float attackDb = n->Param("attack");
      const float sustainDb = n->Param("sustain");

      const float kWindowSec = 0.4f;
      const int kNumPoints = 96;

      auto envAt = [](float t) {
         return t < 0.08f ? (t / 0.08f) : expf(-(t - 0.08f) * 6.0f);
      };

      auto tauAt = [](float tSec) {
         return expf(-tSec / 0.030f);
      };

      float peakDb = -1000.0f;
      float peakX = origin.x, peakY = origin.y;

      dl->PathClear();
      for (int i = 0; i < kNumPoints; i++)
      {
         const float t = (float)i / (float)(kNumPoints - 1);
         const float env = envAt(t);
         const float ampDb = 20.0f * log10f(std::max(env, 1e-4f));
         const float x = origin.x + t * w;
         const float y = TsVizDbToY(ampDb, origin.y, h);
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 60) : IM_COL32(150, 214, 255, 60), 0, 1.5f);

      dl->PathClear();
      for (int i = 0; i < kNumPoints; i++)
      {
         const float t = (float)i / (float)(kNumPoints - 1);
         const float tSec = t * kWindowSec;
         const float env = envAt(t);
         const float tau = tauAt(tSec);
         const float gainDb = attackDb * tau + sustainDb * (1.0f - tau);
         const float ampDb = 20.0f * log10f(std::max(env, 1e-4f)) + gainDb;
         const float x = origin.x + t * w;
         const float y = TsVizDbToY(ampDb, origin.y, h);
         dl->PathLineTo(ImVec2(x, y));
         if (ampDb > peakDb)
         {
            peakDb = ampDb;
            peakX = x;
            peakY = y;
         }
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      const float transientAmount = std::clamp(n->ExtraMeterValue(0), 0.0f, 1.0f);
      dl->AddCircleFilled(ImVec2(peakX, peakY), 3.0f + transientAmount * 4.0f,
                          isLight ? IM_COL32(230, 120, 20, 230) : IM_COL32(255, 196, 120, 230));

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[80];
         snprintf(buf, sizeof(buf), "attack %+.1f dB - sustain %+.1f dB - peak %+.1f dB", attackDb, sustainDb, peakDb);
         SetAudioReadout("transient shaper", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawTransientShaperBody(GraphNode& gn, AudioEffectNode* n)
   {
      char stat[80];
      snprintf(stat, sizeof(stat), "atk %+.1f dB - sus %+.1f dB", n->Param("attack"), n->Param("sustain"));

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawTransientShaperVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(3);
         row.Knob("attack", n->ParamPtr("attack"), -24.0f, 24.0f, "%.1f dB", kKnobLarge);
         row.Knob("sustain", n->ParamPtr("sustain"), -24.0f, 24.0f, "%.1f dB", kKnobLarge);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      EndAudioBody();
   }

   // ---- Stutter --------------------------------------------------------
   // One square per repeat in the cycle ("1/8 -> 8 steps"), click to mute
   // that repeat - a gate over the beat-repeat loop, same idea as Ableton
   // Beat Repeat's per-slice mute grid. Works at any rate/steps setting:
   // the grid always redraws at exactly `steps` squares.
   void DrawStutterGateGrid(AudioEffectNode* n, int steps)
   {
      const float w = gAudioBodyW;
      const float h = 30.0f;
      const float gap = 3.0f;
      const float cellW = (w - gap * (float)(steps - 1)) / (float)steps;
      const ImVec2 rowOrigin = ImGui::GetCursorScreenPos();
      ImDrawList* dl = ImGui::GetWindowDrawList();
      const int mask = (int)(n->Param("gateMask") + 0.5f);

      for (int i = 0; i < steps; i++)
      {
         const ImVec2 p0(rowOrigin.x + (float)i * (cellW + gap), rowOrigin.y);
         const ImVec2 p1(p0.x + cellW, p0.y + h);
         ImGui::PushID(i);
         ImGui::SetCursorScreenPos(p0);
         ImGui::InvisibleButton("step", ImVec2(cellW, h));
         if (ImGui::IsItemClicked())
         {
            PushUndoCheckpoint();
            *n->ParamPtr("gateMask") = (float)(mask ^ (1 << i));
         }
         const bool on = (mask & (1 << i)) != 0;
         const bool hovered = ImGui::IsItemHovered();
         const bool isLight = IsThemeLight();
         const ImU32 col = on ? (isLight ? IM_COL32(30, 110, 230, hovered ? 255 : 220) : IM_COL32(120, 200, 255, hovered ? 255 : 215))
                               : (isLight ? IM_COL32(220, 225, 235, hovered ? 245 : 215) : IM_COL32(56, 60, 74, hovered ? 210 : 160));
         dl->AddRectFilled(p0, p1, col, 3.0f);
         dl->AddRect(p0, p1, ScopeBorderCol(), 3.0f, 0, 1.0f);
         ImGui::PopID();
      }

      ImGui::SetCursorScreenPos(rowOrigin);
      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawStutterBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool sync = n->Param("sync") != 0.0f;
      const int steps = std::clamp((int)(n->Param("steps") + 0.5f), 2, StutterKernel::kMaxGateSteps);

      char stat[80];
      if (sync)
         snprintf(stat, sizeof(stat), "%s - %d steps", MusicTime::RateDivisionName((int)(n->Param("rateDiv") + 0.5f)),
                  steps);
      else
         snprintf(stat, sizeof(stat), "%.0f ms - %d steps", n->Param("timeMs"), steps);

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);

      DrawStutterGateGrid(n, steps);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         // "sync" folded into the row itself (was a standalone checkbox
         // line below the knobs) - one compact row instead of a row plus a
         // line, and rate/time already live right next to the toggle that
         // picks which of the two is showing.
         AudioKnobRow row(3);
         row.Dropdown("sync", { "Synced", "Free" }, sync ? 0 : 1, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("sync") = (i == 0) ? 1.0f : 0.0f;
         });
         if (sync)
         {
            row.Dropdown("rate", MusicTime::RateDivisionList(), (int)(n->Param("rateDiv") + 0.5f), [n](int i) {
               PushUndoCheckpoint();
               *n->ParamPtr("rateDiv") = (float)i;
            });
         }
         else
         {
            row.Knob("time", n->ParamPtr("timeMs"), 20.0f, 2000.0f, "%.0f ms", kKnobLarge);
         }
         row.Knob("steps", n->ParamPtr("steps"), 2.0f, (float)StutterKernel::kMaxGateSteps, "%.0f", kKnobLarge);
         row.End();
      }

      EndAudioBody();
   }

   // ---- Ring Mod ---------------------------------------------------------
   // The modulator waveform itself, one static cycle - the ring-modding
   // oscillator's shape is the node's whole identity (its frequency and
   // waveform, not the input signal, define the sidebands).
   void DrawRingModVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float midY = origin.y + h * 0.5f;
      dl->AddLine(ImVec2(origin.x, midY), ImVec2(br.x, midY), ScopeMidLineCol(), 1.0f);

      const int waveform = std::clamp((int)(n->Param("waveform") + 0.5f), 0, (int)DspMath::kWaveSquare);
      const float amp = h * 0.5f - 6.0f;

      dl->PathClear();
      const int kNumPoints = 128;
      DspMath::PolyBlepOsc previewOsc;
      previewOsc.phaseInc = 2.0 / (double)kNumPoints; // two static cycles across the panel
      for (int i = 0; i < kNumPoints; i++)
      {
         const double phase = (double)i * previewOsc.phaseInc;
         const float v = previewOsc.Generate(waveform, 0.5f, phase);
         const float x = origin.x + (float)i / (float)(kNumPoints - 1) * w;
         const float y = midY - v * amp;
         dl->PathLineTo(ImVec2(x, y));
      }
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[32];
         snprintf(buf, sizeof(buf), "%.0f Hz", n->Param("freq"));
         SetAudioReadout("ring mod", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawRingModBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool analog = n->Param("analog") != 0.0f;
      char stat[80];
      snprintf(stat, sizeof(stat), "%.0f Hz - %.0f%% wet%s", n->Param("freq"), n->mix * 100.0f,
               analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawRingModVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         AudioKnobRow row(3);
         const int waveform = (int)(n->Param("waveform") + 0.5f);
         static const std::vector<std::string> kWaveNames = SynthModes::WaveformTypeSubset(
            { SynthModes::kWaveSine, SynthModes::kWaveTriangle, SynthModes::kWaveSaw, SynthModes::kWaveSquare });
         row.Dropdown("wave", kWaveNames, waveform, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("waveform") = (float)i;
         });
         // Dropdown is a discrete param (RegisterDiscreteParam, keyed by
         // label hash) and never touches gParamCounter, so moving it ahead of
         // the two continuous knobs here does not renumber their ordinals -
         // freq and mix are still assigned gParamCounter in the same relative
         // order as before (see gParamCounter's comment above, ~line 1162).
         row.Knob("freq", n->ParamPtr("freq"), 1.0f, 5000.0f, "%.0f Hz", kKnobLarge);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      {
         // Same tight checkbox-row pattern as Pitch Shift above and as
         // Dynamics/SpecBlur/Switcher already use: maxDia 20 (checkbox frame
         // height) + hasCaptions=false, so the row doesn't reserve a full
         // knob-height-plus-caption-strip below a control whose label prints
         // inline rather than underneath it.
         AudioKnobRow row(3, 20.0f, 8.0f, false);
         bool analogBool = analog;
         if (row.Checkbox("analog##ringModAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Frequency Shifter ----------------------------------------------
   // Comb-displacement visualizer: input partials on the upper row, shifted
   // partials on the lower row with directional arrows showing rigid sideways
   // translation (the defining characteristic of linear frequency shifting vs
   // harmonic pitch scaling), plus a large in-panel numeric Hz readout.
   void DrawFrequencyShifterVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float shift = n->Param("shift");
      const float spread = n->Param("spread");
      const float midX = origin.x + w * 0.5f;
      const float topY = origin.y + h * 0.30f;
      const float botY = origin.y + h * 0.72f;

      // Center frequency axis & rows
      dl->AddLine(ImVec2(origin.x + 12.0f, topY), ImVec2(br.x - 12.0f, topY), ScopeGridCol(), 1.0f);
      dl->AddLine(ImVec2(origin.x + 12.0f, botY), ImVec2(br.x - 12.0f, botY), ScopeGridCol(), 1.0f);
      dl->AddLine(ImVec2(midX, origin.y + 6.0f), ImVec2(midX, br.y - 6.0f), ScopeMidLineCol(), 1.0f);

      // Partials comb: 7 evenly spaced input partials
      const int kNumPartials = 7;
      const float kSpacing = w * 0.085f;
      const float kMaxShiftPix = w * 0.28f;
      const int range = std::clamp((int)(n->Param("range") + 0.5f), 0, 1);
      const float maxShiftSpan = (range == 0) ? 100.0f : 10000.0f;
      const float shiftFrac = std::clamp(shift / maxShiftSpan, -1.0f, 1.0f);
      const float dxL = shiftFrac * kMaxShiftPix;

      // Arrow & shifted partial color: amber for up-shift, coral/magenta for down-shift, blue-grey for zero
      const ImU32 arrowCol = (shift > 0.5f)
         ? (isLight ? IM_COL32(210, 120, 20, 240) : IM_COL32(255, 185, 70, 230))
         : ((shift < -0.5f) ? (isLight ? IM_COL32(220, 40, 70, 240) : IM_COL32(255, 110, 130, 230))
                            : (isLight ? IM_COL32(90, 105, 130, 200) : IM_COL32(140, 160, 195, 180)));

      for (int i = 0; i < kNumPartials; i++)
      {
         const float xIn = midX + (float)(i - kNumPartials / 2) * kSpacing;
         const float xOutL = xIn + dxL;

         // Input partial tick (upper row)
         dl->AddLine(ImVec2(xIn, topY - 7.0f), ImVec2(xIn, topY + 3.0f),
                     isLight ? IM_COL32(70, 90, 130, 220) : IM_COL32(150, 170, 205, 210), 1.5f);

         // Shifted partial tick (lower row)
         dl->AddLine(ImVec2(xOutL, botY - 3.0f), ImVec2(xOutL, botY + 7.0f), arrowCol, 1.8f);

         // Connecting arrow from input to shifted partial
         dl->AddLine(ImVec2(xIn, topY + 3.0f), ImVec2(xOutL, botY - 3.0f), arrowCol, 1.2f);
         if (std::fabs(dxL) > 1.5f || std::fabs(topY - botY) > 5.0f)
         {
            const float arrowSz = 3.0f;
            dl->AddTriangleFilled(ImVec2(xOutL, botY - 2.0f),
                                  ImVec2(xOutL - arrowSz, botY - 2.0f - arrowSz * 1.5f),
                                  ImVec2(xOutL + arrowSz, botY - 2.0f - arrowSz * 1.5f),
                                  arrowCol);
         }

         if (spread > 0.5f)
         {
            const float shiftRFrac = std::clamp((shift + spread) / maxShiftSpan, -1.0f, 1.0f);
            const float dxR = shiftRFrac * kMaxShiftPix;
            const float xOutR = xIn + dxR;
            const ImU32 spreadCol = (shift + spread > 0.5f)
               ? (isLight ? IM_COL32(210, 140, 40, 140) : IM_COL32(255, 205, 110, 120))
               : ((shift + spread < -0.5f) ? (isLight ? IM_COL32(210, 80, 100, 140) : IM_COL32(255, 140, 160, 120))
                                           : (isLight ? IM_COL32(90, 105, 130, 120) : IM_COL32(140, 160, 195, 100)));
            dl->AddLine(ImVec2(xOutR, botY - 2.0f), ImVec2(xOutR, botY + 6.0f), spreadCol, 1.2f);
         }
      }

      char valBuf[64];
      auto FmtFreq = [](float f, char* b, size_t sz, bool withSign) {
         if (std::fabs(f) >= 1000.0f)
            snprintf(b, sz, withSign ? "%+.2f kHz" : "%.2f kHz", f / 1000.0f);
         else
            snprintf(b, sz, withSign ? "%+.0f Hz" : "%.0f Hz", f);
      };

      char sBuf[32], rBuf[32];
      FmtFreq(shift, sBuf, sizeof(sBuf), true);
      if (std::fabs(spread) > 0.5f)
      {
         FmtFreq(shift + spread, rBuf, sizeof(rBuf), true);
         snprintf(valBuf, sizeof(valBuf), "%s / %s", sBuf, rBuf);
      }
      else
      {
         snprintf(valBuf, sizeof(valBuf), "%s", sBuf);
      }

      const ImVec2 textSz = ImGui::CalcTextSize(valBuf);
      dl->AddText(ImVec2(br.x - textSz.x - 10.0f, origin.y + 8.0f),
                  isLight ? IM_COL32(40, 55, 80, 240) : IM_COL32(230, 238, 255, 240), valBuf);

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         SetAudioReadout("freq shift", valBuf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawFrequencyShifterBody(GraphNode& gn, AudioEffectNode* n)
   {
      const bool analog = n->Param("analog") != 0.0f;
      char stat[80];
      const float shiftVal = n->Param("shift");
      if (std::fabs(shiftVal) >= 1000.0f)
         snprintf(stat, sizeof(stat), "%+.2f kHz - %.0f%% fb - %.0f%% wet%s",
                  shiftVal / 1000.0f, n->Param("feedback") * 100.0f, n->mix * 100.0f, analog ? " - analog" : "");
      else
         snprintf(stat, sizeof(stat), "%+.0f Hz - %.0f%% fb - %.0f%% wet%s",
                  shiftVal, n->Param("feedback") * 100.0f, n->mix * 100.0f, analog ? " - analog" : "");

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawFrequencyShifterVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         const int range = std::clamp((int)(n->Param("range") + 0.5f), 0, 1);
         const float shiftLimit = (range == 0) ? 100.0f : 10000.0f;
         static const std::vector<std::string> kRangeOptions = { "fine +/-100", "wide +/-10k" };
         const char* fmt = (range == 0) ? "%+.1f Hz" : (std::fabs(shiftVal) >= 1000.0f ? "%+.2f kHz" : "%+.0f Hz");

         AudioKnobRow row(4, kKnobLarge, ImGui::GetFrameHeight() + 5.0f);
         row.DropdownKnob("fsRange", kRangeOptions, range,
                          [n](int i) {
                             PushUndoCheckpoint();
                             *n->ParamPtr("range") = (float)i;
                          },
                          "shift", n->ParamPtr("shift"), -shiftLimit, shiftLimit, fmt, false, kKnobLarge);
         row.Knob("feedback", n->ParamPtr("feedback"), 0.0f, 0.95f, "%.2f", kKnobLarge);
         row.Knob("spread", n->ParamPtr("spread"), 0.0f, 100.0f, "%.1f Hz", kKnobLarge, false, false, AudioWidgetStyle::KnobSkewSpread100);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      {
         AudioKnobRow row(4, 20.0f, 8.0f, false);
         bool analogBool = analog;
         if (row.Checkbox("analog##freqShiftAnalog", &analogBool))
         {
            PushUndoCheckpoint();
            *n->ParamPtr("analog") = analogBool ? 1.0f : 0.0f;
         }
         row.Skip();
         row.Skip();
         row.Skip();
         row.End();
      }

      EndAudioBody();
   }

   // ---- Tremolo --------------------------------------------------------
   // The resulting *gain envelope*, not the raw bipolar LFO - a filled area
   // from the panel top down to the curve so the eye reads "how much signal
   // survives" directly, exactly what a tremolo pedal's amplitude modulation
   // does and Ring Mod's raw-oscillator preview (above) deliberately does
   // not - see TremoloKernel.h's class comment on the distinction. The right
   // channel's envelope overlays as a second, dimmer stroke whenever
   // `stereoPhase` is non-zero, since that knob is otherwise invisible.
   void DrawTremoloVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const int shape = std::clamp((int)(n->Param("shape") + 0.5f), 0, 3);
      const int dspWaveform = TremoloKernel::ShapeToDspWaveform(shape);
      const bool rampDown = shape == 3;
      const float depth = std::clamp(n->Param("depth"), 0.0f, 1.0f);
      const float stereoPhaseCycles = std::clamp(n->Param("stereoPhase"), 0.0f, 180.0f) / 360.0f;

      DspMath::PolyBlepOsc previewOsc;
      previewOsc.phaseInc = 2.0 / (double)128; // two static cycles across the panel

      auto envelopeY = [&](double phase) {
         float lfo = previewOsc.Generate(dspWaveform, 0.5f, phase);
         if (rampDown)
            lfo = -lfo;
         const float gain = TremoloKernel::GainFromLfo(lfo, depth);
         return br.y - gain * h;
      };

      const int kNumPoints = 128;
      ImVec2 envPts[kNumPoints];
      for (int i = 0; i < kNumPoints; i++)
      {
         const double phase = (double)i * previewOsc.phaseInc;
         const float x = origin.x + (float)i / (float)(kNumPoints - 1) * w;
         envPts[i] = ImVec2(x, envelopeY(phase));
      }
      for (int i = 0; i < kNumPoints - 1; i++)
         dl->AddQuadFilled(envPts[i], envPts[i + 1], ImVec2(envPts[i + 1].x, br.y), ImVec2(envPts[i].x, br.y),
                            isLight ? IM_COL32(30, 110, 230, 45) : IM_COL32(150, 214, 255, 60));

      dl->PathClear();
      for (int i = 0; i < kNumPoints; i++)
         dl->PathLineTo(envPts[i]);
      dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 255) : IM_COL32(150, 214, 255, 245), 0, 1.8f);

      if (stereoPhaseCycles > 0.0f)
      {
         dl->PathClear();
         for (int i = 0; i < kNumPoints; i++)
         {
            const double phase = (double)i * previewOsc.phaseInc + stereoPhaseCycles;
            const float x = origin.x + (float)i / (float)(kNumPoints - 1) * w;
            dl->PathLineTo(ImVec2(x, envelopeY(phase)));
         }
         dl->PathStroke(isLight ? IM_COL32(30, 110, 230, 110) : IM_COL32(150, 214, 255, 110), 0, 1.4f);
      }

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[32];
         const bool sync = n->Param("sync") != 0.0f;
         if (sync)
         {
            const int rateDiv = (int)(n->Param("rateDiv") + 0.5f);
            const double bpm = std::max(1.0, (double)Transport::Instance().Tempo());
            const double rateHz = MusicTime::HzForRateDivision((MusicTime::RateDivision)rateDiv, bpm);
            snprintf(buf, sizeof(buf), "%s (%.1f Hz)", MusicTime::RateDivisionName(rateDiv), rateHz);
         }
         else
            snprintf(buf, sizeof(buf), "%.1f Hz", n->Param("rate"));
         SetAudioReadout("tremolo", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

   void DrawTremoloBody(GraphNode& gn, AudioEffectNode* n)
   {
      char stat[64];
      snprintf(stat, sizeof(stat), "%.0f%% depth - %.0f%% wet", n->Param("depth") * 100.0f, n->mix * 100.0f);

      BeginAudioBody(gn.index, gn.category, kAudioNodeWidth, stat);
      DrawTremoloVisualizer(n);
      ImGui::Dummy(ImVec2(0.0f, 4.0f));

      {
         // Selector column left (shape v), knobs right (depth, stereo).
         // The dropdown is a discrete param (numbered from a hash of its
         // label - DiscreteParamSlot) rather than a gParamCounter ordinal,
         // so calling it first here costs "depth"/"stereo" nothing - they
         // still get the same ordinals (0, 1) they always have.
         AudioKnobRow row(3);
         const int shape = (int)(n->Param("shape") + 0.5f);
         static const std::vector<std::string> kShapeNames = SynthModes::WaveformTypeSubset(
            { SynthModes::kWaveSine, SynthModes::kWaveTriangle, SynthModes::kWaveSquare, SynthModes::kWaveRampDown });
         row.Dropdown("shape", kShapeNames, shape, [n](int i) {
            PushUndoCheckpoint();
            *n->ParamPtr("shape") = (float)i;
         });
         row.Knob("depth", n->ParamPtr("depth"), 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.Knob("stereo", n->ParamPtr("stereoPhase"), 0.0f, 180.0f, "%.0f deg", kKnobLarge);
         row.End();
      }
      {
         // Selector column left (mode v, rate), mix bottom-right (P4). Rate
         // is still called before mix, exactly as before, so mix's ordinal
         // doesn't move.
         AudioKnobRow row(3);
         AddRateModeCells(row, n, "sync to tempo##tremoloSync", 0.05f, 20.0f);
         row.Knob("mix", &n->mix, 0.0f, 1.0f, "%.2f", kKnobLarge);
         row.End();
      }

      EndAudioBody();
   }

   // ---- Formant Filter -----------------------------------------------------
   // The three formant resonators' frequencies as markers on a log axis -
   // the picture a filter's own frequency-response curve would give, but
   // for three narrow bandpass peaks rather than one broad shape, so three
   // labelled markers reads more clearly than a busy triple-peaked curve.
   void DrawFormantFilterVisualizer(AudioEffectNode* n)
   {
      const float w = gAudioBodyW;
      const float h = kAudioTimeVizH;
      const ImVec2 origin = ImGui::GetCursorScreenPos();
      const ImVec2 br(origin.x + w, origin.y + h);
      ImDrawList* dl = ImGui::GetWindowDrawList();

      const bool isLight = IsThemeLight();
      dl->AddRectFilled(origin, br, ScopeBgCol(), 4.0f);
      dl->PushClipRect(origin, br, true);

      const float logMin = log10f(100.0f), logMax = log10f(5000.0f);
      auto freqToX = [&](float hz) {
         const float t = std::clamp((log10f(hz) - logMin) / (logMax - logMin), 0.0f, 1.0f);
         return origin.x + t * w;
      };

      for (float hz : { 100.0f, 300.0f, 1000.0f, 3000.0f })
      {
         const float x = freqToX(hz);
         dl->AddLine(ImVec2(x, origin.y), ImVec2(x, br.y), ScopeGridCol(), 1.0f);
      }

      const FormantDsp::Formants f = FormantDsp::VowelFormants(n->Param("vowel"));
      const float formants[3] = { f.f1, f.f2, f.f3 };
      const float weights[3] = { 1.0f, 0.7f, 0.5f };
      static const char* kFormantLabels[3] = { "F1", "F2", "F3" };
      for (int i = 0; i < 3; i++)
      {
         const float x = freqToX(formants[i]);
         const float peakY = br.y - 6.0f - weights[i] * (h - 20.0f);
         dl->AddLine(ImVec2(x, br.y - 6.0f), ImVec2(x, peakY),
                     isLight ? IM_COL32(30, 110, 230, 230) : IM_COL32(150, 214, 255, 220), 3.0f);
         dl->AddText(ImVec2(x - 7.0f, peakY - 14.0f), ScopeTextCol(), kFormantLabels[i]);
      }

      dl->PopClipRect();
      dl->AddRect(origin, br, ScopeBorderCol(), 3.0f);

      if (ImGui::IsMouseHoveringRect(origin, br))
      {
         char buf[64];
         snprintf(buf, sizeof(buf), "F1 %.0f - F2 %.0f - F3 %.0f Hz", f.f1, f.f2, f.f3);
         SetAudioReadout("formant filter", buf);
      }

      ImGui::Dummy(ImVec2(w, h));
   }

