         constexpr double kToneHz = 440.0;
         constexpr double kToneSampleRate = 48000.0;
         constexpr double kToneSeconds = 1.5;
         constexpr float kToneAmplitude = 0.5f;
         const int toneFrames = (int)(kToneSampleRate * kToneSeconds);
