         SpawnNode("Particle System", "3D", 40.0f, 40.0f);       // 0: the shared source
         SpawnNode("Render 3D", "3D", 320.0f, 40.0f);            // 1
         SpawnNode("Instance on Points", "3D", 320.0f, 260.0f);  // 2
